def _canonical_workato_db_value(value: Any) -> Any:
    """Normalize Workato's canonical storage form for boolean columns."""

    if isinstance(value, dict):
        return {key: _canonical_workato_db_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_canonical_workato_db_value(item) for item in value]
    if isinstance(value, str) and value.lower() in {"true", "false"}:
        return value.lower()
    if value is not None and not isinstance(value, bool):
        return str(value)
    return value


def _expected_menu_catch_payload(expect: dict[str, Any]) -> dict[str, Any]:
    return {
        "5968e436": {
            "type": expect.get("catch_type"),
            "message": expect.get("catch_error"),
            "adapter": expect.get("catch_adapter"),
            "action": expect.get("catch_action"),
            "line_number": expect.get("catch_line_number"),
        }
    }


def _without_anon_tags(value: Any) -> Any:
    """Remove dataset anonymization markup from rendered user-visible text."""

    if not isinstance(value, str):
        return value
    return value.replace("<anon>", "").replace("</anon>", "")


def _workato_deleted_record_logs_match(expected: Any, actual: Any) -> bool:
    """Compare legacy Python-rendered fixtures with Ruby/Workato log output.

    Older fixtures stored the row payload with Python ``repr`` and omitted the
    connector's derived ``record_id`` alias.  Neither representation choice is
    an orchestration difference, so normalize the fixture payload to the Ruby
    rendering used by the raw executor and accept the documented alias.
    """

    if not isinstance(expected, list) or not isinstance(actual, list) or len(expected) != len(actual):
        return False
    prefix = "[WRKSM] DELETED REQUEST RECORD\n\n"
    record_id_field = "11fbe9a6_a16d_4d7e_86ea_afe42ec03005"
    for expected_message, actual_message in zip(expected, actual):
        if expected_message == actual_message:
            continue
        if not isinstance(expected_message, str) or not expected_message.startswith(prefix):
            return False
        try:
            payload = ast.literal_eval(expected_message[len(prefix):])
        except (SyntaxError, ValueError):
            return False
        if not isinstance(payload, dict):
            return False
        candidates = [payload]
        if record_id_field in payload:
            candidates.append({**payload, "record_id": payload[record_id_field]})
        if actual_message not in {prefix + ruby_inspect(candidate) for candidate in candidates}:
            return False
    return True


def verify_result(result: dict[str, Any]) -> dict[str, Any]:
    recipe_id = result.get("recipe_id")
    fn = globals().get(f"verify_{recipe_id}") if recipe_id is not None else None
    if callable(fn):
        return fn(result)
    raise RuntimeError(f"no verifier registered for recipe {recipe_id}")


def _verify_50802627_manual(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    selected_table_id = str(details.get("selected_table_id") or "")
    untouched_table_id = str(details.get("untouched_table_id") or "")
    entry_id = str(details.get("entry_id") or "")
    expected_entry = details.get("expected_entry") or {}
    returned_result = details.get("returned_result") or {}
    initial_snapshot = details.get("initial_snapshot") or {}
    final_snapshot = details.get("final_snapshot") or {}
    raw_execution = details.get("raw_execution") or {}
    tool_calls = result.get("tool_calls") or []
    update_call = _find_call(tool_calls, "lookup_table.update_entry")
    args = (update_call or {}).get("args") or {}
    tables = final_snapshot.get("lookup_table", {}).get("tables", {})
    selected_rows = tables.get(selected_table_id, [])
    matching_rows = [
        row for row in selected_rows
        if isinstance(row, dict)
        and (str(row.get("id")) == entry_id or str(row.get("_row_id")) == entry_id)
    ]
    initial_untouched_rows = (
        initial_snapshot.get("lookup_table", {})
        .get("tables", {})
        .get(untouched_table_id, [])
    )
    final_untouched_rows = tables.get(untouched_table_id, [])
    expected_return = {
        "email": expected_entry.get("col1"),
        "remarks": expected_entry.get("col2"),
        "description": expected_entry.get("col3"),
        "claim_type": expected_entry.get("col4"),
        "claim_amount": expected_entry.get("col5"),
        "approved_amount": expected_entry.get("col6"),
        "approval_status": expected_entry.get("col7"),
        "receipt_link": expected_entry.get("col8"),
        "employee_threadid": expected_entry.get("col9"),
        "channel_permalink": expected_entry.get("col10"),
    }
    checks = [
        _check(
            "recipe_updated_lookup_entry",
            bool(update_call and _ok(update_call)),
            {"tool": "lookup_table.update_entry", "result": (update_call or {}).get("result")},
        ),
        _check(
            "update_called_on_selected_ledger",
            bool(
                args.get("lookup_table_id") == selected_table_id
                and str(args.get("id")) == entry_id
                and args.get("parameters") == details.get("expected_update")
            ),
            {
                "expected_table": selected_table_id,
                "expected_id": entry_id,
                "expected_update": details.get("expected_update"),
                "actual_args": args,
            },
        ),
        _check(
            "selected_ledger_has_updated_preserved_entry",
            bool(
                len(matching_rows) == 1
                and all(str(matching_rows[0].get(key)) == str(value) for key, value in expected_entry.items())
            ),
            {
                "table_id": selected_table_id,
                "entry_id": entry_id,
                "matching_rows": matching_rows,
            },
        ),
        _check(
            "other_ledger_unchanged",
            final_untouched_rows == initial_untouched_rows,
            {
                "table_id": untouched_table_id,
                "initial_rows": initial_untouched_rows,
                "final_rows": final_untouched_rows,
            },
        ),
        _check(
            "returned_current_entry_state",
            returned_result == expected_return,
            {"expected_return": expected_return, "actual_return": returned_result},
        ),
        _raw_execution_path_check(raw_execution, 2),
    ]
    return {"ok": _checks_ok(checks), "checks": checks}


