def _verify_53837831_manual(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    expected_query = str(details.get("expected_query") or "")
    expected_total = str(details.get("expected_total_spent_hours") or "")
    cleanup_response = details.get("cleanup_response") or {}
    raw_execution = details.get("raw_execution") or {}
    tool_calls = result.get("tool_calls") or []
    harness_calls = (result.get("harness_tool_calls") or []) + (details.get("seed_harness_tool_calls") or [])
    seed_call = _find_call(harness_calls, "harness.salesforce.seed_records")
    search_call = _find_call(tool_calls, "salesforce.search_records")
    return_call = _find_call(tool_calls, "workato_recipe_function.return_result")
    search_args = (search_call or {}).get("args") or {}
    search_result = (search_call or {}).get("result") or {}
    return_args = (return_call or {}).get("args") or {}
    returned_result = (return_call or {}).get("result") or {}
    result_payload = return_args.get("result") if isinstance(return_args.get("result"), dict) else {}
    returned_payload = returned_result.get("result") if isinstance(returned_result.get("result"), dict) else {}
    checks = [
        _check(
            "seed_created_live_salesforce_records",
            bool(seed_call and _ok(seed_call)),
            {"tool": "harness.salesforce.seed_records", "result": (seed_call or {}).get("result")},
        ),
        _check(
            "recipe_searched_live_salesforce",
            bool(search_call and _ok(search_call) and search_result.get("count", 0) >= 1),
            {"tool": "salesforce.search_records", "result": search_result},
        ),
        _check(
            "search_used_expected_soql",
            bool(search_args.get("sobject") == "Task" and search_args.get("query") == expected_query),
            {"expected_query": expected_query, "actual_args": search_args},
        ),
        _check(
            "recipe_returned_mocked_workato_result",
            bool(return_call and _ok(return_call)),
            {"tool": "workato_recipe_function.return_result", "result": returned_result},
        ),
        _check(
            "returned_expected_total_spent_hours",
            # expected_total is independently recomputed by run_53837831 from
            # the SEEDED Task records (Hours_Spent__c over the records matching
            # the recipe query's declared filters), never from the recipe's own
            # return - so this compares the recipe's returned total against a
            # seed-derived groundtruth instead of echoing it back (fails closed
            # when the independent value is missing).
            bool(
                expected_total
                and str(result_payload.get("total_spent_hours")) == expected_total
                and str(returned_payload.get("total_spent_hours")) == expected_total
            ),
            {
                "expected_total_spent_hours": expected_total,
                "expected_total_source": details.get("expected_total_source"),
                "actual_args": return_args,
                "actual_result": returned_result,
            },
        ),
        _check(
            "live_salesforce_seed_records_cleaned_up",
            bool(cleanup_response.get("ok") and not cleanup_response.get("leftovers")),
            {"cleanup_response": cleanup_response},
        ),
        _raw_execution_path_check(raw_execution, 2),
    ]
    return {"ok": _checks_ok(checks), "checks": checks}


