    returned = returned_result.get("result") if isinstance(returned_result.get("result"), dict) else {}
    cleanup = details.get("cleanup_response") if isinstance(details.get("cleanup_response"), dict) else {}
    checks = list(base.get("checks") or [])
    # Branch-aware: the upsert's primary_key Id match routes to create OR
    # update. The expected outcome is gated on the variant's own expect
    # (the genie result_contains status pin); variants without a pinned
    # status keep the created-path default.
