def _genie_invalid_id_catch_checks(result: dict[str, Any]) -> list[dict[str, Any]]:
    # Catch#8 -> IF#9 ('invalid ID field') -> STOP#10 pins for the
    # 128662267/129809019 genie contact-create pair. Callers gate on
    # expect.stopped is True, so existing variants never reach here.
    CATCH_STEP = "3264b66c"
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    tool_calls = result.get("tool_calls") or []
    checks: list[dict[str, Any]] = []
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "invalid_id_stop_is_final_trace_row_at_step_10",
        len(stop_rows) == 1
        and bool(trace)
        and trace[-1] is stop_rows[0]
        and str(stop_rows[0].get("as") or "") == "388f1687"
        and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number")),
        {
            "reason": "the invalid-ID branch must stop at catch-arm STOP #10/388f1687 — "
                      "NOT at the zero-result STOP #7/a5b5d45a (trace stop rows carry no "
                      "stop_reason; the branch is discriminated by the stop row identity "
                      "and the catch payload)",
            "expected_stop": {"as": "388f1687", "number": expect.get("stop_step_number")},
            "stop_rows": stop_rows,
        },
    ))
    catch_payload = (raw_execution.get("step_outputs") or {}).get(CATCH_STEP)
    checks.append(_check(
        "catch_payload_matches_exactly",
        catch_payload == expect.get("catch"),
        {
            "reason": "engine-canonical catch payload {type: RawRecipeExecutionError, "
                      "message: <forced live-style MALFORMED_QUERY text>} pinned exactly",
            "expected_catch": expect.get("catch"),
            "actual_catch": catch_payload,
        },
    ))
    checks.append(_check(
        "catch_message_contains_invalid_id_field",
        "invalid ID field" in str((catch_payload or {}).get("message") or ""),
        {
            "reason": "IF #9's own predicate: catch.message CONTAINS 'invalid ID field' "
                      "is what routes to STOP #10",
            "actual_catch": catch_payload,
        },
    ))
    checks.append(_check(
        "no_search_create_or_return_calls_on_catch_branch",
        not [
            call for call in tool_calls
            if str(call.get("tool") or "") in {
                "salesforce.search_records",
                "salesforce.create_record",
                "workato_genie.workflow_return_result",
            }
        ],
        {
            "reason": "the search raised before the adapter boundary and the stop "
                      "precedes create #11 / return #12",
            "tool_calls": tool_calls,
        },
    ))
    checks.append(_check(
        "stopped_run_has_no_return_value",
        raw_execution.get("return_value") is None,
        {"return_value": raw_execution.get("return_value")},
    ))
    cleanup_response = details.get("cleanup_response") or {}
    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))
    return checks


def verify_128662267(result: dict[str, Any]) -> dict[str, Any]:
    strict = _verify_strict_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    if expect.get("stopped") is not True:
        return strict
    checks = list(strict.get("checks") or []) + _genie_invalid_id_catch_checks(result)
    return {"ok": _checks_ok(checks), "checks": checks}


