def verify_119839249(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    tool_calls = result.get("tool_calls") or []
    checks = list(replay.get("checks") or [])
    expected_trace_tools = expect.get("trace_tools")
    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    if isinstance(expected_trace_tools, list):
        checks.append(_check(
            "raw_trace_tools_match_expected",
            actual_trace_tools == expected_trace_tools,
            {"expected_trace_tools": expected_trace_tools, "actual_trace_tools": actual_trace_tools},
        ))
    if "response" in expect:
        expected_response = expect.get("response")
        return_call = _find_call(tool_calls, "workato_api_platform.return_response")
        return_result = (return_call or {}).get("result") or {}

        def without_derived_record_id(value: Any) -> Any:
            if isinstance(value, list):
                return [without_derived_record_id(item) for item in value]
            if not isinstance(value, dict):
                return value
            normalized = {
                key: without_derived_record_id(child)
                for key, child in value.items()
            }
            record_id = normalized.get("record_id")
            if record_id is not None and any(
                key != "record_id"
                and re.fullmatch(r"[0-9a-f]{8}(?:_[0-9a-f]{4}){3}_[0-9a-f]{12}", str(key))
                and child == record_id
                for key, child in normalized.items()
            ):
                normalized.pop("record_id", None)
            return normalized

        actual_return = without_derived_record_id(
            raw_execution.get("return_value")
        )
        actual_response = without_derived_record_id(
            return_result.get("response")
        )
        checks.extend([
            _check(
                "raw_return_value_matches_expected_response_semantically",
                actual_return == expected_response,
                {"expected_response": expected_response, "actual_return_value": raw_execution.get("return_value")},
            ),
            _check(
                "api_response_matches_expected_response_semantically",
                actual_response == expected_response,
                {"expected_response": expected_response, "actual_return_result": return_result},
            ),
        ])
    logger_contains = expect.get("logger_message_contains")
    if isinstance(logger_contains, str):
        logger_messages = [
            str((row.get("result") or {}).get("message") or "")
            for row in trace
            if isinstance(row, dict) and row.get("tool") == "workato_runtime.log_message"
        ]
        checks.append(_check(
            "logger_message_contains_expected_text",
            any(logger_contains in message for message in logger_messages),
            {"expected_text": logger_contains, "logger_messages": logger_messages},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


