def verify_120645392(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    checks = list(replay.get("checks") or [])
    final_tables = (
        (details.get("final_snapshot") or {})
        .get("workato_db_table", {})
        .get("tables", {})
    )
    expected_counts = expect.get("final_table_counts")
    if isinstance(expected_counts, dict):
        for table_id, expected_count in expected_counts.items():
            rows = final_tables.get(str(table_id), [])
            checks.append(_check(
                f"final_table_{table_id}_row_count_matches",
                isinstance(rows, list) and len(rows) == expected_count,
                {"table_id": table_id, "expected_count": expected_count, "actual_rows": rows},
            ))
    expected_rows = expect.get("final_rows")
    if isinstance(expected_rows, list):
        for idx, item in enumerate(expected_rows):
            if not isinstance(item, dict):
                checks.append(_check("final_row_expectation_is_object", False, {"index": idx, "value": item}))
                continue
            table_id = str(item.get("table_id") or "")
            rows = final_tables.get(table_id, [])
            match = item.get("match") if isinstance(item.get("match"), dict) else {}
            fields = item.get("fields") if isinstance(item.get("fields"), dict) else match
            matches = [
                row for row in rows
                if isinstance(row, dict)
                and all(str(row.get(key)) == str(value) for key, value in match.items())
            ]
            checks.append(_check(
                f"final_row_{idx}_matches_expected_fields",
                bool(matches and any(
                    all(str(row.get(key)) == str(value) for key, value in fields.items())
                    for row in matches
                )),
                {"table_id": table_id, "match": match, "fields": fields, "matching_rows": matches},
            ))
    return {"ok": _checks_ok(checks), "checks": checks}


