def verify_117385101(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    final_tables = (final_snapshot.get("workato_db_table") or {}).get("tables") or {}
    cleanup_response = details.get("cleanup_response") or {}
    checks = list(replay.get("checks") or [])

    expected_segment = expect.get("sales_team_segment_conversion")
    segment_rows = [
        row for row in trace
        if isinstance(row, dict)
        and row.get("tool") == "workato_runtime.declare_variable"
        and "sales_team_segment_conversion" in (row.get("result") or {})
    ]
    actual_segment = (segment_rows[0].get("result") or {}).get("sales_team_segment_conversion") if segment_rows else None
    checks.append(_check(
        "sales_team_segment_conversion_matches_expected",
        bool(segment_rows) and str(actual_segment) == str(expected_segment),
        {"expected": expected_segment, "actual": actual_segment, "trace": segment_rows},
    ))

    expected_counts = expect.get("final_table_counts")
    if not isinstance(expected_counts, dict) or not expected_counts:
        checks.append(_check("expect_final_table_counts_present", False, {"expect": expect}))
    else:
        for table_id, expected_count in expected_counts.items():
            rows = final_tables.get(str(table_id), [])
            checks.append(_check(
                f"final_table_{table_id}_row_count_matches",
                isinstance(rows, list) and len(rows) == expected_count,
                {"table_id": table_id, "expected_count": expected_count, "actual_rows": rows},
            ))

    expected_rows = expect.get("final_table_contains")
    if not isinstance(expected_rows, list) or not expected_rows:
        checks.append(_check("expect_final_table_contains_present", False, {"expect": expect}))
    else:
        for idx, item in enumerate(expected_rows):
            if not isinstance(item, dict):
                checks.append(_check(f"expected_final_table_row_{idx}_is_object", False, {"value": item}))
                continue
            table_id = str(item.get("table_id") or "")
            fields = item.get("fields") if isinstance(item.get("fields"), dict) else {}
            rows = final_tables.get(table_id, [])
            matches = [
                row for row in rows
                if isinstance(row, dict)
                and all(str(row.get(key)) == str(value) for key, value in fields.items())
            ]
            checks.append(_check(
                f"final_table_expected_row_{idx}_present",
                bool(table_id and fields and matches),
                {"table_id": table_id, "fields": fields, "matching_rows": matches, "rows": rows},
            ))

    checks.append(_check(
        "salesforce_backend_untouched_by_recipe",
        bool(
            isinstance(initial_snapshot.get("salesforce"), dict)
            and initial_snapshot.get("salesforce") == final_snapshot.get("salesforce")
        ),
        {
            "initial_salesforce": initial_snapshot.get("salesforce"),
            "final_salesforce": final_snapshot.get("salesforce"),
        },
    ))

    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok") and not cleanup_response.get("leftovers")),
        {"cleanup_response": cleanup_response},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


