def _verify_feedback_sheet_family(result: dict[str, Any]) -> dict[str, Any]:
    """Verify the shared feedback-sheet outcome without owning a recipe ID."""

    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    final_sheet = (details.get("final_snapshot") or {}).get("google_sheets") or {}
    rows = final_sheet.get("rows") if isinstance(final_sheet.get("rows"), list) else []
    checks = list(replay.get("checks") or [])
    expected_rows = expect.get("sheet_rows")
    if isinstance(expected_rows, list):
        missing: list[dict[str, Any]] = []
        for expected_row in expected_rows:
            if not isinstance(expected_row, dict):
                missing.append({"invalid_expected_row": expected_row})
                continue
            match = any(
                isinstance(row, dict)
                and all(
                    _sheet_value_matches(row.get(key, ""), value)
                    for key, value in expected_row.items()
                )
                for row in rows
            )
            if not match:
                missing.append(expected_row)
        checks.append(_check(
            "final_sheet_contains_expected_feedback_rows",
            not missing,
            {
                "expected_rows": expected_rows,
                "missing_rows": missing,
                "final_rows": rows,
            },
        ))
    if "final_row_count" in expect:
        checks.append(_check(
            "final_sheet_row_count_matches",
            len(rows) == expect.get("final_row_count"),
            {
                "expected_count": expect.get("final_row_count"),
                "actual_count": len(rows),
                "final_rows": rows,
            },
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


