def verify_50801166(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    missing = [key for key in ("return_result", "booking_branch") if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 50801166 variant must pin expect.return_result "
                          "(exact elements payload) and expect.booking_branch (cancel|book)",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    return_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_recipe_function.return_result"
    ]
    checks.append(_check(
        "return_fired_once_at_step_15",
        len(return_rows) == 1 and str(return_rows[0].get("number")) == "15",
        {"return_rows": return_rows},
    ))
    checks.append(_check(
        "return_value_matches_expected_exactly",
        raw_execution.get("return_value") == expect.get("return_result"),
        {
            "expected_return_result": expect.get("return_result"),
            "actual_return_value": raw_execution.get("return_value"),
        },
    ))
    branch = expect.get("booking_branch")
    elements = ""
    if isinstance(raw_execution.get("return_value"), dict):
        elements = str(raw_execution["return_value"].get("elements") or "")
    cancel_present = '"text": "Cancel my Locker Booking"' in elements
    book_present = '"text": "Book a Locker"' in elements
    if branch not in {"cancel", "book"}:
        checks.append(_check(
            "expect_booking_branch_invalid",
            False,
            {"reason": "expect.booking_branch must be 'cancel' or 'book'", "value": branch},
        ))
    else:
        checks.append(_check(
            "returned_elements_carry_exactly_the_branch_button",
            (cancel_present and not book_present) if branch == "cancel"
            else (book_present and not cancel_present),
            {
                "expected_branch": branch,
                "cancel_button_present": cancel_present,
                "book_button_present": book_present,
                "elements": elements,
            },
        ))
    initial_snapshot = details.get("initial_snapshot")
    final_snapshot = details.get("final_snapshot")
    checks.append(_check(
        "lookup_tables_untouched_by_read_only_recipe",
        bool(initial_snapshot) and initial_snapshot == final_snapshot,
        {"initial_snapshot": initial_snapshot, "final_snapshot": final_snapshot},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


