def verify_92416709(result: dict[str, Any]) -> dict[str, Any]:
    LOOKUP_TABLE_ID = "2343001"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    table_id = str(details.get("lookup_table_id") or LOOKUP_TABLE_ID)
    initial_rows = _lookup_rows(details.get("initial_snapshot"), table_id)
    final_rows = _lookup_rows(details.get("final_snapshot"), table_id)
    target = details.get("target_entry") if isinstance(details.get("target_entry"), dict) else {}
    channel = str(target.get("col3") or "")
    ts = str(target.get("col4") or "")

    target_absent = not any(
        str(row.get("col3")) == channel and str(row.get("col4")) == ts
        for row in final_rows
        if isinstance(row, dict)
    )
    checks.append(_check(
        "pending_check_entry_removed_from_lookup",
        bool(channel and ts and target_absent),
        {"target": target, "final_rows": final_rows},
    ))
    checks.append(_check(
        "only_target_entry_removed",
        len(final_rows) == max(len(initial_rows) - 1, 0),
        {"initial_count": len(initial_rows), "final_count": len(final_rows)},
    ))

    seed_message = details.get("seed_message") if isinstance(details.get("seed_message"), dict) else {}
    delete_call = _find_call(result.get("tool_calls") or [], "slack.post_reply")
    delete_args = (delete_call or {}).get("args") or {}
    delete_result = (delete_call or {}).get("result") or {}
    checks.append(_check(
        "original_message_deleted_from_channel",
        bool(
            delete_call
            and delete_result.get("ok")
            and str(delete_args.get("channel")) == str(seed_message.get("channel"))
            and str(delete_args.get("original_ts")) == str(seed_message.get("ts"))
            and delete_args.get("delete_original") is True
        ),
        {"seed_message": seed_message, "delete_args": delete_args, "delete_result": delete_result},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}

