    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    final_sheet = (details.get("final_snapshot") or {}).get("google_sheets") or {}
    rows = final_sheet.get("rows") if isinstance(final_sheet.get("rows"), list) else []
    checks = list(replay.get("checks") or [])
    expected_trace_tools = expect.get("trace_tools")
    if isinstance(expected_trace_tools, list):
        actual_trace_tools = [
            row.get("tool")
            for row in trace
            if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
        ]
        checks.append(_check(
            "raw_trace_tools_match_expected",
            actual_trace_tools == expected_trace_tools,
            {"expected_trace_tools": expected_trace_tools, "actual_trace_tools": actual_trace_tools},
        ))
    else:
        checks.append(_check(
            "expect_trace_tools_missing",
            False,
            {
                "reason": "recipe 23260621 variants must pin expect.trace_tools "
                          "(logger + sheets append + return_result raw trace)",
                "expect": expect,
            },
        ))
    expected_row = expect.get("sheet_row")
    if isinstance(expected_row, dict) and expected_row:
        matching_rows = [
            row for row in rows
            if isinstance(row, dict)
            and all(_sheet_value_matches(row.get(key, ""), value) for key, value in expected_row.items())
        ]
        checks.append(_check(
            "final_sheet_contains_expected_signup_row",
            bool(matching_rows),
            {"expected_row": expected_row, "matching_rows": matching_rows, "final_rows": rows},
        ))
    else:
        checks.append(_check(
            "expect_sheet_row_missing",
            False,
            {
                "reason": "recipe 23260621 variants must pin the full 14-column "
                          "expect.sheet_row ground truth",
                "expect": expect,
            },
        ))
    if "final_row_count" in expect:
        checks.append(_check(
            "final_sheet_row_count_matches",
            len(rows) == expect.get("final_row_count"),
            {"expected_count": expect.get("final_row_count"), "actual_count": len(rows), "final_rows": rows},
        ))
    else:
        checks.append(_check(
            "expect_final_row_count_missing",
            False,
            {
                "reason": "recipe 23260621 variants must pin expect.final_row_count",
                "expect": expect,
            },
        ))
    logger_contains = expect.get("logger_message_contains")
    if isinstance(logger_contains, str):
        logger_messages = [
            str((row.get("result") or {}).get("message") or "")
            for row in trace
            if isinstance(row, dict) and row.get("tool") == "workato_runtime.log_message"
        ]
        checks.append(_check(
            "logger_message_contains_expected_text",
            any(logger_contains in message for message in logger_messages),
            {"expected_text": logger_contains, "logger_messages": logger_messages},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


