def verify_127934002(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "recipe 127934002 has no stop steps", "stop_rows": stop_rows},
    ))
    expected_result = expect.get("result")
    trigger_parameters = (details.get("trigger") or {}).get("parameters") or {}
    method = str(trigger_parameters.get("method") or "").upper()
    routed_method = method in {"GET", "POST", "PUT", "DELETE"}
    checks.append(_check(
        "return_value_matches_expected_result",
        (
            isinstance(expected_result, dict)
            and bool(expected_result)
            if routed_method
            else expected_result is None
        )
        and raw_execution.get("return_value") == expected_result,
        {
            "reason": "routed methods pin their exact result; unsupported free-text "
                      "methods pin null for the recipe's no-op fallthrough",
            "method": method,
            "expected_result": expected_result,
            "actual_return_value": raw_execution.get("return_value"),
        },
    ))
    counts = expect.get("final_table_counts")
    if isinstance(counts, dict) and counts:
        for table_id, expected_count in counts.items():
            rows = _workato_db_final_rows_127934002(details, str(table_id))
            checks.append(_check(
                f"final_table_{table_id}_row_count_matches",
                len(rows) == expected_count,
                {"table_id": table_id, "expected_count": expected_count, "actual_count": len(rows)},
            ))
    else:
        checks.append(_check(
            "expect_final_table_counts_missing",
            False,
            {
                "reason": "every 127934002 variant must pin expect.final_table_counts for "
                          "table 45816 (add/update/delete side effects are the ground truth)",
                "expect": expect,
            },
        ))
    for label, want_present in (("final_table_contains", True), ("final_table_not_contains", False)):
        entries = expect.get(label)
        if entries is None:
            continue
        if not isinstance(entries, list):
            checks.append(_check(f"expect_{label}_is_list", False, {"value": entries}))
            continue
        for idx, item in enumerate(entries):
            table_id = str((item or {}).get("table_id") or "")
            fields = (item or {}).get("fields")
            if not table_id or not isinstance(fields, dict) or not fields:
                checks.append(_check(
                    f"{label}_{idx}_is_well_formed",
                    False,
                    {"reason": f"{label} items need table_id + non-empty fields", "item": item},
                ))
                continue
            rows = _workato_db_final_rows_127934002(details, table_id)
            matching = [row for row in rows if _row_fields_match_127934002(row, fields)]
            checks.append(_check(
                f"{label}_{idx}_{'row_present' if want_present else 'row_absent'}",
                bool(matching) is want_present,
                {"table_id": table_id, "fields": fields, "matching_rows": matching, "row_count": len(rows)},
            ))
    return {"ok": _checks_ok(checks), "checks": checks}


