        actual_campaigns = reply.get("campaigns") if isinstance(reply.get("campaigns"), list) else None
        campaigns_ok = isinstance(actual_campaigns, list) and len(actual_campaigns) == len(expected_campaigns)
        if campaigns_ok:
            for expected_row, actual_row in zip(expected_campaigns, actual_campaigns):
                if not isinstance(expected_row, dict) or not isinstance(actual_row, dict):
                    campaigns_ok = False
                    break
                if actual_row.get("campaign_name") != expected_row.get("campaign_name"):
                    campaigns_ok = False
                    break
                expected_joined = expected_row.get("joined")
                actual_joined = actual_row.get("joined")
                if expected_joined == "__ANY__":
                    if not (isinstance(actual_joined, str) and actual_joined):
                        campaigns_ok = False
                        break
                elif actual_joined != expected_joined:
                    campaigns_ok = False
                    break
        checks.append(_check(
            "campaigns_match_expected",
            campaigns_ok,
            {"expected_campaigns": expected_campaigns, "actual_campaigns": actual_campaigns},
        ))
