    if isinstance(sheet_read, dict):
        first_cell = None
        if sheets_rows:
            result_rows = (sheets_rows[0].get("result") or {}).get("rows") or []
            if result_rows and isinstance(result_rows[0], dict):
                first_cell = result_rows[0].get("col_Please link the Landing Page")
        checks.append(_check(
            "sheets_read_first_row_col_matches_expected",
            len(sheets_rows) == 1 and first_cell == sheet_read.get("col_value"),
            {
                "expected_col_value": sheet_read.get("col_value"),
                "actual_first_cell": first_cell,
                "sheets_calls": len(sheets_rows),
            },
        ))
    else:
        checks.append(_check(
            "no_sheets_read_expected_or_executed",
            not sheets_rows,
            {"sheets_rows": sheets_rows},
        ))

    catch_ids = ("c84bedec", "4a01c237", "6db36320")
    expected_catch = expect.get("catch")
    if isinstance(expected_catch, dict):
        catch_as = str(expected_catch.get("as") or "")
        catch_payload = step_outputs.get(catch_as) if isinstance(step_outputs.get(catch_as), dict) else {}
        checks.append(_check(
            "catch_swallowed_expected_forced_error",
            str(catch_payload.get("type") or "") == str(expected_catch.get("type") or "")
            and str(catch_payload.get("message") or "") == str(expected_catch.get("message") or ""),
            {"expected_catch": expected_catch, "actual_payload": catch_payload},
        ))
    else:
        fired = {catch_id: step_outputs[catch_id] for catch_id in catch_ids if catch_id in step_outputs}
        checks.append(_check(
            "no_catch_expected_or_fired",
            not fired,
            {"fired_catches": fired},
        ))

    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    snapshot_records = ((final_snapshot.get("salesforce") or {}).get("records") or [])
    ca_id = str(expect.get("final_ca_id") or "")
    final_ca_fields: dict[str, Any] = {}
    for record in snapshot_records:
        if isinstance(record, dict) and str(record.get("id") or "") == ca_id:
            fields = record.get("fields")
            final_ca_fields = fields if isinstance(fields, dict) else {}
            break
    expected_final_ca = expect.get("final_ca") if isinstance(expect.get("final_ca"), dict) else {}
    final_ca_ok = bool(final_ca_fields) and bool(expected_final_ca)
    final_mismatches: dict[str, Any] = {}
    for key, value in expected_final_ca.items():
        if final_ca_fields.get(key) != value:
            final_ca_ok = False
            final_mismatches[key] = {"expected": value, "actual": final_ca_fields.get(key)}
    checks.append(_check(
        "final_campaign_activity_fields_match_expected",
        final_ca_ok,
        {
            "final_ca_id": ca_id,
            "expected_final_ca": expected_final_ca,
            "actual_fields": final_ca_fields,
            "mismatches": final_mismatches,
        },
    ))

    cleanup = details.get("salesforce_cleanup") if isinstance(details.get("salesforce_cleanup"), dict) else {}
    checks.append(_check(
        "salesforce_cleanup_ok_with_zero_leftovers",
        cleanup.get("ok") is True and not cleanup.get("leftovers"),
        {"cleanup": cleanup},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


