def _substitute_sentinel_91033101(value: Any, sentinel: str, replacement: str) -> Any:
    if isinstance(value, dict):
        return {
            key: _substitute_sentinel_91033101(item, sentinel, replacement)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [_substitute_sentinel_91033101(item, sentinel, replacement) for item in value]
    if isinstance(value, str) and sentinel in value:
        return value.replace(sentinel, replacement)
    return value


def _contains_sentinel_91033101(value: Any, sentinel: str) -> bool:
    if isinstance(value, dict):
        return any(_contains_sentinel_91033101(item, sentinel) for item in value.values())
    if isinstance(value, list):
        return any(_contains_sentinel_91033101(item, sentinel) for item in value)
    return isinstance(value, str) and sentinel in value


def verify_91033101(result: dict[str, Any]) -> dict[str, Any]:
    LOOKUP_TABLE_ID = "3357221"
    CATCH_KEY = "38bfd4f3"
    SENTINEL = "__POSTED_TS_EPOCH__"
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    missing = [key for key in ("lookup_final_tables", "catch_used", "col7_write") if key not in expect]
    if expect.get("catch_used") is True and "forced_error_message" not in expect:
        missing.append("forced_error_message")
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 91033101 variant must pin expect.lookup_final_tables "
                          "(sentinel for derived col7), expect.catch_used (+ "
                          "forced_error_message when true) and expect.col7_write",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    post_rows = _trace_rows_91033101(details, "slack.post_message")
    update_rows = _trace_rows_91033101(details, "lookup_table.update_entry")
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    request = trigger.get("request") if isinstance(trigger.get("request"), dict) else {}
    raw_literals = {str(request.get("user") or ""), str(request.get("channel_id") or "")}
    checks.append(_check(
        "posted_channels_never_raw_trigger_literals",
        all(
            str((row.get("args") or {}).get("channel") or "")
            and str((row.get("args") or {}).get("channel") or "") not in raw_literals
            for row in post_rows
        ),
        {
            "reason": "the seeded 'U...' user and the fake channel_id must never leak "
                      "into a live post: user ids are routed via seed.slack_channel_map "
                      "and non-user channels via SLACK_CHANNEL_OVERRIDE",
            "raw_literals": sorted(raw_literals),
            "post_rows": post_rows,
        },
    ))
    checks.append(_check(
        "posts_returned_live_ts",
        all(str((row.get("result") or {}).get("ts") or "") for row in post_rows),
        {"post_rows": post_rows},
    ))
    derived_epoch: int | None = None
    if expect.get("col7_write") is True:
        col7_ok = (
            len(post_rows) == 1
            and len(update_rows) == 1
            and str((post_rows[0].get("result") or {}).get("ts") or "")
        )
        if col7_ok:
            derived_epoch = int(float(str(post_rows[0]["result"]["ts"])))
            update_args = update_rows[0].get("args") or {}
            col7_ok = (
                str(update_args.get("lookup_table_id") or "") == LOOKUP_TABLE_ID
                and (update_args.get("parameters") or {}) == {"col7": derived_epoch}
            )
        checks.append(_check(
            "col7_write_matches_posted_ts",
            bool(col7_ok),
            {
                "reason": "the write branches post exactly once and write back exactly "
                          "col7 = int(float(posted ts)) -- derived from the live trace, "
                          "never a pinned literal",
                "derived_epoch": derived_epoch,
                "post_rows": post_rows,
                "update_rows": update_rows,
            },
        ))
    else:
        checks.append(_check(
            "no_col7_write_occurred",
            not update_rows,
            {"update_rows": update_rows},
        ))
    catch_data = (raw_execution.get("data") or {}).get("catch") or {}
    catch_payload = catch_data.get(CATCH_KEY) if isinstance(catch_data.get(CATCH_KEY), dict) else None
    checks.append(_check(
        "catch_branch_usage_matches_expected",
        (catch_payload is not None) is bool(expect.get("catch_used")),
        {"expected_catch_used": expect.get("catch_used"), "actual_catch_data": catch_data},
    ))
    if expect.get("catch_used") is True:
        checks.append(_check(
            "catch_payload_carries_forced_error_message",
            bool(catch_payload)
            and str(catch_payload.get("message") or "") == str(expect.get("forced_error_message") or ""),
            {
                "expected_message": expect.get("forced_error_message"),
                "actual_catch_payload": catch_payload,
            },
        ))
    expected_tables = expect.get("lookup_final_tables")
    if isinstance(expected_tables, dict) and derived_epoch is not None:
        expected_tables = _substitute_sentinel_91033101(expected_tables, SENTINEL, str(derived_epoch))
    final_tables = (
        ((details.get("final_snapshot") or {}).get("lookup_table") or {}).get("tables")
    )
    checks.append(_check(
        "lookup_final_tables_match",
        isinstance(expected_tables, dict)
        and not _contains_sentinel_91033101(expected_tables, SENTINEL)
        and final_tables == expected_tables,
        {
            "reason": "table 3357221 must hold exactly the seeded rows with col7 "
                      "rewritten to the derived posted-ts epoch on write variants and "
                      "byte-identical seed state on read-only/catch variants",
            "expected_tables": expected_tables,
            "actual_tables": final_tables,
        },
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


