def verify_109041941(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    expected_trace_tools = expect.get("trace_tools")
    if isinstance(expected_trace_tools, list):
        checks.append(_check(
            "raw_trace_tools_match_expected",
            actual_trace_tools == expected_trace_tools,
            {"expected_trace_tools": expected_trace_tools, "actual_trace_tools": actual_trace_tools},
        ))
    else:
        checks.append(_check(
            "expect_trace_tools_missing",
            False,
            {"reason": "recipe 109041941 variants must pin expect.trace_tools", "expect": expect},
        ))
    # STOP semantics: a stop marker exists iff expect.stopped, it sits at raw
    # step 11 as the FINAL trace row, and the step-12 update_variables never
    # runs after it (the whole job halts mid-loop).
    stop_rows = [
        row for row in trace if isinstance(row, dict) and row.get("stopped") is True
    ]
    expected_stopped = expect.get("stopped")
    if expected_stopped is True:
        stop_ok = (
            len(stop_rows) == 1
            and stop_rows[0].get("number") == 11
            and bool(trace)
            and trace[-1] is stop_rows[0]
            and "workato_runtime.update_variables" not in actual_trace_tools
        )
    else:
        stop_ok = expected_stopped is False and not stop_rows
    checks.append(_check(
        "stop_marker_matches_expected",
        stop_ok,
        {
            "expected_stopped": expected_stopped,
            "stop_rows": stop_rows,
            "trace_tail": trace[-1] if trace else None,
        },
    ))
    # Pagination cursor pins: one entry per get_records call; '<omitted>' means
    # the args must NOT carry continuation_token at all (the SKIP sentinel is
    # suppressed on the first page), later pages pass the seeded token verbatim.
    actual_tokens = [
        (row.get("args") or {}).get("continuation_token")
        if "continuation_token" in (row.get("args") or {})
        else "<omitted>"
        for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_db_table.get_records"
    ]
    checks.append(_check(
        "continuation_token_args_match_expected",
        isinstance(expect.get("continuation_tokens"), list)
        and actual_tokens == expect["continuation_tokens"],
        {"expected_tokens": expect.get("continuation_tokens"), "actual_tokens": actual_tokens},
    ))
    # Final mock-table pin: the harness snapshot must equal the expected rows
    # exactly (catch variants pin the written error/retry row; read-only
    # variants pin the untouched seed).
    final_snapshot = details.get("final_snapshot") or {}
    actual_rows = (
        final_snapshot.get("workato_db_table", {})
        .get("tables", {})
        .get("17244")
    )
    checks.append(_check(
        "final_table_rows_match_expected",
        isinstance(expect.get("final_table_rows"), list)
        and actual_rows == expect["final_table_rows"],
        {"expected_rows": expect.get("final_table_rows"), "actual_rows": actual_rows},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


