def verify_90485335(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    required = (
        "stopped",
        "stop_step_number",
        "stop_step_as",
        "searched_name",
        "rt_filter_id",
        "final_fields_by_name",
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 90485335 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "clean_stop_is_final_trace_row",
        bool(expect.get("stopped"))
        and len(stop_rows) == 1
        and bool(trace)
        and trace[-1] is stop_rows[0]
        and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number"))
        and str(stop_rows[0].get("as") or "") == str(expect.get("stop_step_as")),
        {
            "reason": "every live-reachable path ends at a clean stop: 5/c8723ba4 on the "
                      "customer arm, 10/e28e0a52 on the partner arm (stop_with_error=false "
                      "pinned in the raw structure)",
            "expected_stop": {
                "number": expect.get("stop_step_number"),
                "as": expect.get("stop_step_as"),
            },
            "stop_rows": stop_rows,
            "trace_tail": trace[-1] if trace else None,
        },
    ))

    update_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "salesforce.update_record"
    ]
    checks.append(_check(
        "dead_update_branches_never_executed",
        not update_rows,
        {
            "reason": "steps 6/11 sit behind a search filtered on a source-org "
                      "RecordTypeId no live record can carry; an executed update means "
                      "the dead-branch proof no longer holds",
            "update_rows": update_rows,
        },
    ))

    final_records = ((details.get("final_snapshot") or {}).get("salesforce") or {}).get("records") or []
    fields_by_name: dict[str, Any] = {}
    for record in final_records:
        if not isinstance(record, dict) or record.get("sobject") != "Account":
            continue
        fields = record.get("fields") if isinstance(record.get("fields"), dict) else {}
        fields_by_name[str(fields.get("Name") or "")] = fields

    searched_name = str(expect.get("searched_name") or "")
    decoy_fields = fields_by_name.get(searched_name)
    checks.append(_check(
        "zero_match_attributable_to_rt_filter",
        isinstance(decoy_fields, dict)
        and decoy_fields.get("RecordTypeId") != expect.get("rt_filter_id"),
        {
            "reason": "a live decoy Account carrying the search's EXACT Name filter must "
                      "exist while its real live RecordTypeId differs from the hardcoded "
                      "source-org id -- proving the 0-result comes from the RT filter, "
                      "not an empty org",
            "searched_name": searched_name,
            "expected_rt_filter_id": expect.get("rt_filter_id"),
            "decoy_fields": decoy_fields,
        },
    ))

    expected_fields = expect.get("final_fields_by_name")
    fields_ok = isinstance(expected_fields, dict) and bool(expected_fields)
    if fields_ok:
        for name, expected_subset in expected_fields.items():
            actual = fields_by_name.get(str(name))
            if not isinstance(actual, dict) or not isinstance(expected_subset, dict):
                fields_ok = False
                break
            for key, value in expected_subset.items():
                if actual.get(key) != value:
                    fields_ok = False
                    break
            if not fields_ok:
                break
    checks.append(_check(
        "final_live_fields_match_expected_by_name",
        fields_ok,
        {
            "reason": "both live Accounts keep Customer_is_a_Partner__c null (the dead "
                      "update steps never write), read from the final snapshot before "
                      "cleanup",
            "expected_fields_by_name": expected_fields,
            "actual_fields_by_name": fields_by_name,
        },
    ))

    cleanup_response = details.get("cleanup_response") or {}
    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


def verify_123864475(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])
    from benchmark.argument_semantics import compare_response_full

    response_boolean_paths = {
        path[1:]
        for path in _expected_boolean_paths(
            expect, "workato_api_platform.return_response"
        )
        if path and path[0] == "response"
    }

    requested_id = expect.get("requested_account_id")
    is_stop = expect.get("stopped") is True
    required = ("requested_account_id",) + (
        ("stop_step_number", "stop_step_as") if is_stop else ("http_status_code", "response")
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": f"every 123864475 variant must pin {missing} (stop variants pin "
                          "the stop step; response variants pin the exact body + status)",
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    response_calls = [
        call
        for call in result.get("tool_calls") or []
        if isinstance(call, dict) and call.get("tool") == "workato_api_platform.return_response"
    ]
    return_value = raw_execution.get("return_value")

    if is_stop:
        checks.append(_check(
            "not_found_stop_is_final_trace_row",
            len(stop_rows) == 1
            and bool(trace)
            and trace[-1] is stop_rows[0]
            and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number"))
            and str(stop_rows[0].get("as") or "") == str(expect.get("stop_step_as")),
            {
                "reason": "the empty get makes IF-4 false; the else-stop (7 / cf26d231, "
                          "stop_with_error=true 'No records found' pinned in the raw "
                          "structure) ends the job immediately",
                "expected_stop": {
                    "number": expect.get("stop_step_number"),
                    "as": expect.get("stop_step_as"),
                },
                "stop_rows": stop_rows,
                "trace_tail": trace[-1] if trace else None,
            },
        ))
        checks.append(_check(
            "stop_is_not_routed_to_catch",
            not response_calls and return_value is None,
            {
                "reason": "a stop is recipe control flow, not an action error: neither "
                          "return_response (252ace50 nor the catch's edfa1c85) may "
                          "execute and the endpoint returns no body",
                "response_calls": response_calls,
                "return_value": return_value,
            },
        ))
        final_records = ((details.get("final_snapshot") or {}).get("salesforce") or {}).get("records") or []
        live_ids = [str(row.get("id") or "") for row in final_records if isinstance(row, dict)]
        checks.append(_check(
            "zero_match_attributable_to_requested_id",
            bool(live_ids) and str(requested_id) not in live_ids,
            {
                "reason": "a live decoy Account exists while the requested id matches no "
                          "live record -- the empty get comes from the id, not an empty org",
                "requested_account_id": requested_id,
                "live_account_ids": live_ids,
            },
        ))
    else:
        checks.append(_check(
            "api_response_matches_expected_semantically",
            compare_response_full(
                "workato_api_platform.return_response",
                return_value,
                expect.get("response"),
                boolean_paths=response_boolean_paths,
            ),
            {"expected_response": expect.get("response"), "actual_return_value": return_value},
        ))
        last_response = response_calls[-1] if response_calls else None
        last_result = (last_response or {}).get("result") or {}
        checks.append(_check(
            "return_response_call_carries_expected_body_and_status",
            bool(
                last_response
                and last_result.get("ok") is True
                and compare_response_full(
                    "workato_api_platform.return_response",
                    last_result.get("response"),
                    expect.get("response"),
                    boolean_paths=response_boolean_paths,
                )
                and str(last_result.get("http_status_code") or "") == str(expect.get("http_status_code") or "")
            ),
            {
                "expected_http_status_code": expect.get("http_status_code"),
                "expected_response": expect.get("response"),
                "actual_call": last_response,
            },
        ))
        checks.append(_check(
            "no_stop_occurred",
            not stop_rows,
            {"reason": "response variants never reach the else-stop", "stop_rows": stop_rows},
        ))

    if "get_record_fields" in expect:
        get_rows = [
            row for row in trace
            if isinstance(row, dict) and str(row.get("as") or "") == "a495f9f5"
        ]
        get_result = (get_rows[0].get("result") or {}) if get_rows else {}
        expected_fields = expect.get("get_record_fields")
        fields_ok = isinstance(expected_fields, dict) and bool(expected_fields) and all(
            get_result.get(key) == value for key, value in expected_fields.items()
        )
        checks.append(_check(
            "get_result_grounds_response_in_live_readback",
            len(get_rows) == 1 and fields_ok,
            {
                "reason": "the found-path response bytes (events text, url id) must come "
                          "from the live get read-back of THIS run's seeded Account",
                "expected_fields": expected_fields,
                "actual_get_result": get_result,
            },
        ))

    if "catch_message" in expect:
        catch_payload = ((raw_execution.get("data") or {}).get("catch") or {}).get("86806634")
        checks.append(_check(
            "catch_payload_matches_forced_error",
            isinstance(catch_payload, dict)
            and catch_payload.get("message") == expect.get("catch_message"),
            {
                "reason": "the edfa1c85 body.error interpolates the 86806634 catch "
                          "payload message (pinned literal forced-error bytes)",
                "expected_message": expect.get("catch_message"),
                "actual_catch_payload": catch_payload,
            },
        ))

    cleanup = details.get("cleanup_response")
    if cleanup is not None:
        checks.append(_check(
            "salesforce_cleanup_removed_owned_records",
            isinstance(cleanup, dict)
            and cleanup.get("ok") is True
            and not (cleanup.get("leftovers") or []),
            {"cleanup_response": cleanup},
        ))

    return {"ok": _checks_ok(checks), "checks": checks}


