def verify_129421288(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    posted_texts = expect.get("posted_texts")
    expected_stopped = expect.get("stopped")
    if not isinstance(posted_texts, list) or not isinstance(expected_stopped, bool):
        checks.append(_check(
            "expect_declares_posted_texts_and_stop_outcome",
            False,
            {
                "reason": "every 129421288 variant must declare expect.posted_texts (exact "
                          "ordered list, may be empty) and a boolean expect.stopped",
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    post_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack.post_message"
    ]
    actual_texts = [str((row.get("args") or {}).get("text") or "") for row in post_rows]
    checks.append(_check(
        "posted_texts_match_expected_exactly",
        actual_texts == posted_texts,
        {
            "reason": "one DM per found CS-CSM email, in success_owner_email ORDER BY order",
            "expected_texts": posted_texts,
            "actual_texts": actual_texts,
        },
    ))

    channel_map = details.get("slack_channel_map")
    channel_map = channel_map if isinstance(channel_map, dict) else {}
    bad_channels = [
        str((row.get("args") or {}).get("channel") or "")
        for row in post_rows
        if not str((row.get("args") or {}).get("channel") or "")
        or str((row.get("args") or {}).get("channel") or "").startswith("U")
    ]
    checks.append(_check(
        "posts_never_target_raw_user_dm",
        not bad_channels,
        {
            "reason": "the resolved live user id must be redirected via seed.slack_channel_map "
                      "to the benchmark override channel; a U-prefixed or empty post channel "
                      "means a real DM would have been sent",
            "bad_channels": bad_channels,
            "post_rows": post_rows,
        },
    ))

    lookup_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.get_user_by_email"
    ]
    found_ids = [
        str((row.get("result") or {}).get("id") or "")
        for row in lookup_rows
        if (row.get("result") or {}).get("id")
    ]
    checks.append(_check(
        "every_found_user_id_is_mapped",
        all(uid in channel_map for uid in found_ids),
        {
            "reason": "each live-resolved user id must appear in seed.slack_channel_map so the "
                      "DM is provably redirected",
            "found_ids": found_ids,
            "slack_channel_map": channel_map,
        },
    ))
    checks.append(_check(
        "one_post_per_found_user",
        (
            len(post_rows) == len(found_ids)
            if expected_stopped is False
            else len(post_rows) <= len(found_ids)
        ),
        {
            "reason": "normal runs post once per found user; a declared fault may interrupt "
                      "the current lookup/post pair before its write",
            "found_ids": found_ids,
            "post_count": len(post_rows),
            "expected_stopped": expected_stopped,
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "catch_stop_outcome_matches_expected",
        (
            not stop_rows
            if expected_stopped is False
            else len(stop_rows) == 1 and stop_rows[0].get("number") == 9
        )
        and raw_execution.get("return_value") is None,
        {
            "reason": "normal runs do not stop; a hash-bound fault-injection variant must "
                      "reach exactly the recipe's catch STOP step 9",
            "expected_stopped": expected_stopped,
            "stop_rows": stop_rows,
        },
    ))

    initial_snapshot = details.get("initial_snapshot")
    final_snapshot = details.get("final_snapshot")
    seeded_tables = (
        ((initial_snapshot or {}).get("snowflake") or {}).get("tables")
        if isinstance(initial_snapshot, dict)
        else None
    )
    expected_tables = {
        "edw_db.salesforce.conversation",
        "workato_business_systems.salesforce.account",
        "workato_business_systems.salesforce.user",
        "workato_business_systems.salesforce.user_role",
    }
    checks.append(_check(
        "live_tables_unchanged_by_run",
        isinstance(initial_snapshot, dict)
        and isinstance(seeded_tables, dict)
        and expected_tables <= set(seeded_tables)
        and initial_snapshot == final_snapshot,
        {
            "reason": "the recipe only reads the four seeded tables; live pre/post snapshots "
                      "must be identical",
            "initial_snapshot": initial_snapshot,
            "final_snapshot": final_snapshot,
        },
    ))

    cleanup = ((details.get("cleanup_response") or {}).get("snowflake_live") or {})
    checks.append(_check(
        "snowflake_cleanup_dropped_seeded_tables",
        bool(cleanup.get("ok"))
        and expected_tables <= set(cleanup.get("dropped_tables") or []),
        {"cleanup_response": details.get("cleanup_response")},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


