    accumulate_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.accumulate_list_items"
    ]
    expected_users = expected_result.get("Users") or []
    accumulated_ok = len(accumulate_rows) == len(expected_users)
    if accumulated_ok and expected_users:
        final_items = (accumulate_rows[-1].get("result") or {}).get("list_items")
        accumulated_ok = final_items == expected_users
