def verify_125461407(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    required = ("slack_text", "trace_tools", "channel_source")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 125461407 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_tool_sequence_matches_expected",
        actual_trace_tools == expect.get("trace_tools"),
        {
            "reason": "the ordered declare/insert/post sequence pins which presence "
                      "IFs fired (inserts are workato_runtime steps outside "
                      "allowed_tools, so the strict block alone cannot see them)",
            "expected_trace_tools": expect.get("trace_tools"),
            "actual_trace_tools": actual_trace_tools,
        },
    ))

    slack_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack.post_message"
    ]
    slack_args = (slack_rows[0].get("args") or {}) if slack_rows else {}
    checks.append(_check(
        "slack_post_text_matches_exactly",
        len(slack_rows) == 1
        and slack_args.get("text") == expect.get("slack_text")
        and bool(slack_args.get("channel")),
        {
            "reason": "exact render: pretext + title + attachment_text + one "
                      "'Name: value' line per inserted field, posted to the "
                      "(non-empty) override channel",
            "expected_text": expect.get("slack_text"),
            "slack_rows": slack_rows,
        },
    ))

    message = ((details.get("trigger") or {}).get("message") or {})
    error_channel_blank = not str(message.get("error_channel") or "").strip()
    expected_source = expect.get("channel_source")
    checks.append(_check(
        "channel_source_consistent_with_trigger",
        (expected_source == "account_property") == error_channel_blank
        and expected_source in ("message", "account_property"),
        {
            "reason": "channel = message.error_channel.presence || account property: "
                      "a blank error_channel and only a blank one takes the fallback "
                      "arm (the property is seeded exactly in that case)",
            "expected_channel_source": expected_source,
            "trigger_error_channel": message.get("error_channel"),
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "125461407 has no stop steps; every variant runs to the post", "stop_rows": stop_rows},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


def verify_111073966(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup_response = (details.get("cleanup_response") or {}).get("snowflake_live") or {}
    checks = list(replay.get("checks") or [])

    if "stopped" not in expect:
        checks.append(_check(
            "expect_declares_stop_outcome",
            False,
            {
                "reason": "every 111073966 variant must declare expect.stopped explicitly",
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "stop_outcome_matches_expected",
        bool(stop_rows) is bool(expect.get("stopped")),
        {"expected_stopped": expect.get("stopped"), "stop_rows": stop_rows},
    ))
    if expect.get("stopped"):
        checks.append(_check(
            "stop_occurred_at_expected_step",
            [row.get("number") for row in stop_rows] == [expect.get("stop_step_number")],
            {
                "reason": "step 4 = charge schedule gate, 7 = payment term gate, "
                          "10 = currency gate, 13 = subsidiary gate",
                "expected_stop_step_number": expect.get("stop_step_number"),
                "stop_rows": stop_rows,
            },
        ))
        checks.append(_check(
            "stopped_run_did_not_return_result",
            not [
                row for row in trace
                if isinstance(row, dict) and row.get("tool") == "workato_recipe_function.return_result"
            ],
            {"trace": trace},
        ))
        checks.append(_check(
            "stopped_run_has_no_return_value",
            raw_execution.get("return_value") is None,
            {"return_value": raw_execution.get("return_value")},
        ))
    else:
        expected_result = expect.get("result")
        checks.append(_check(
            "return_value_matches_expected_result",
            isinstance(expected_result, dict) and raw_execution.get("return_value") == expected_result,
            {
                "reason": "the four ids are engine-produced strings (integer_conversion "
                          "in the result schema is not applied by the engine)",
                "expected_result": expected_result,
                "actual_return_value": raw_execution.get("return_value"),
            },
        ))

    checks.append(_check(
        "snowflake_backend_untouched_by_recipe",
        bool(
            isinstance(initial_snapshot.get("snowflake_live"), dict)
            and initial_snapshot.get("snowflake_live") == final_snapshot.get("snowflake_live")
        ),
        {
            "reason": "the recipe only searches Snowflake; the live snapshot must be "
                      "identical before and after the run",
            "initial_snowflake": initial_snapshot.get("snowflake_live"),
            "final_snowflake": final_snapshot.get("snowflake_live"),
        },
    ))

    dropped = cleanup_response.get("dropped_tables")
    checks.append(_check(
        "live_snowflake_seed_tables_cleaned_up",
        bool(cleanup_response.get("ok"))
        and isinstance(dropped, list)
        and sorted(dropped) == [
            "NETSUITE.CURRENCY",
            "NETSUITE.PAYMENT_TERM",
            "NETSUITE.SUBSIDIARY",
        ],
        {"cleanup_response": cleanup_response},
    ))

    checks.append(_check(
        "workato_db_table_untouched_by_recipe",
        bool(
            isinstance(initial_snapshot.get("workato_db_table"), dict)
            and initial_snapshot.get("workato_db_table", {}).get("tables")
            == final_snapshot.get("workato_db_table", {}).get("tables")
        ),
        {
            "reason": "table 1831 is read-only for this recipe",
            "initial_tables": initial_snapshot.get("workato_db_table", {}).get("tables"),
            "final_tables": final_snapshot.get("workato_db_table", {}).get("tables"),
        },
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


