def verify_94382842(result: dict[str, Any]) -> dict[str, Any]:
    DECLARE_STEP = "36bf1d17"
    UPDATE_STEP = "d719ef1b"
    CATCH_STEP = "31cbad55"
    TABLE_KEY = "WORKATO_BUSINESS_SYSTEMS.FRESHDESK.product_support_ticket_export"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}

    required = ("resolved_sql", "menu_options", "menu_options_ordered", "final_job_report")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 94382842 variant must pin expect.resolved_sql, "
                          "expect.menu_options (null on the catch branch), "
                          "expect.menu_options_ordered and expect.final_job_report",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    catch_branch = expect.get("menu_options") is None
    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    expected_trace = (
        ["workato_runtime.declare_variable", "workato_runtime.update_variables"]
        if catch_branch
        else [
            "workato_runtime.declare_variable",
            "snowflake.search_rows_sql",
            "slack_bot.generate_menu_options",
        ]
    )
    checks.append(_check(
        "trace_tool_sequence_matches_branch",
        trace_tools == expected_trace,
        {
            "reason": "TRY completes declare -> live search -> menu; the forced-error "
                      "catch branch runs declare -> update_variables only (the failed "
                      "snowflake action never traces)",
            "expected_trace": expected_trace,
            "actual_trace": trace_tools,
        },
    ))

    search_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "snowflake.search_rows_sql"
    ]
    if catch_branch:
        checks.append(_check(
            "catch_branch_never_reached_snowflake",
            not search_rows and expect.get("resolved_sql") is None,
            {
                "reason": "force_action_error fires before the adapter runs — no live "
                          "SQL may execute and resolved_sql must be pinned null",
                "expected_resolved_sql": expect.get("resolved_sql"),
                "actual_search_rows": search_rows,
            },
        ))
    else:
        search_args = (search_rows[0].get("args") or {}) if search_rows else {}
        checks.append(_check(
            "resolved_sql_matches_exactly",
            len(search_rows) == 1
            and search_args.get("sql") == expect.get("resolved_sql")
            and search_args.get("limit") == 2000,
            {
                "reason": "exactly one live search; the SQL must carry the typeahead "
                          "interpolated verbatim into LOWER('%…%') and the raw limit "
                          "'2000' (the live client appends it)",
                "expected_sql": expect.get("resolved_sql"),
                "actual_args": search_args,
            },
        ))

    menu_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.generate_menu_options"
    ]
    if catch_branch:
        checks.append(_check(
            "catch_branch_rendered_no_menu",
            not menu_rows,
            {"reason": "the TRY branch aborted before the menu step", "actual_rows": menu_rows},
        ))
    else:
        menu_options = (menu_rows[0].get("result") or {}).get("options") if menu_rows else None
        expected_options = expect.get("menu_options")
        if expect.get("menu_options_ordered"):
            options_match = menu_options == expected_options
        else:
            # No ORDER BY in the SQL: compare as a multiset.
            def _option_key(option):
                if not isinstance(option, dict):
                    return ("", "")
                return (str(option.get("label")), str(option.get("value")))

            options_match = (
                isinstance(menu_options, list)
                and isinstance(expected_options, list)
                and sorted(menu_options, key=_option_key) == sorted(expected_options, key=_option_key)
            )
        checks.append(_check(
            "menu_options_match_expected",
            len(menu_rows) == 1 and options_match,
            {
                "reason": "one menu render; options = one {label,value} per DISTINCT "
                          "matched company name ([] when nothing matched); multiset "
                          "compare when menu_options_ordered is false (no ORDER BY)",
                "expected_options": expected_options,
                "ordered": expect.get("menu_options_ordered"),
                "actual_rows": menu_rows,
            },
        ))
        checks.append(_check(
            "menu_labels_equal_values",
            all(
                isinstance(option, dict) and option.get("label") == option.get("value")
                for option in (menu_options or [])
            ),
            {
                "reason": "the recipe maps company_name into BOTH label and value",
                "actual_options": menu_options,
            },
        ))

    declare_state = step_outputs.get(DECLARE_STEP)
    job_report = declare_state.get("job_report") if isinstance(declare_state, dict) else None
    checks.append(_check(
        "declared_job_report_matches",
        job_report == expect.get("final_job_report"),
        {
            "reason": "job_report stays 'OK' when the TRY completes and must flip to "
                      "'Failed' on the DECLARED step when the catch fires",
            "expected": expect.get("final_job_report"),
            "actual": job_report,
        },
    ))

    variable_steps = raw_execution.get("data", {}).get("workato_variable", {})
    variable_keys = sorted(variable_steps.keys()) if isinstance(variable_steps, dict) else None
    allowed_keys = {DECLARE_STEP, UPDATE_STEP}
    checks.append(_check(
        "no_phantom_variable_steps",
        isinstance(variable_steps, dict) and set(variable_steps.keys()) <= allowed_keys,
        {
            "reason": "the catch update must land on the declared step — a write to any "
                      "other key (e.g. an anon-token phantom, the 94382824 twin failure "
                      "mode) is wrong groundtruth",
            "allowed_steps": sorted(allowed_keys),
            "actual_steps": variable_keys,
        },
    ))

    if catch_branch:
        catch_payload = step_outputs.get(CATCH_STEP)
        checks.append(_check(
            "catch_recorded_forced_error",
            isinstance(catch_payload, dict) and bool(str(catch_payload.get("message") or "").strip()),
            {
                "reason": "the catch block records the forced snowflake error payload",
                "actual_payload": catch_payload,
            },
        ))
        checks.append(_check(
            "catch_branch_owns_no_live_state",
            details.get("initial_snapshot") == {} and details.get("final_snapshot") == {},
            {
                "reason": "catch variants seed no Snowflake table, so there is nothing "
                          "to snapshot or clean up",
                "initial_snapshot": details.get("initial_snapshot"),
                "final_snapshot": details.get("final_snapshot"),
            },
        ))
    else:
        initial_tables = ((details.get("initial_snapshot") or {}).get("snowflake") or {}).get("tables")
        final_tables = ((details.get("final_snapshot") or {}).get("snowflake") or {}).get("tables")
        checks.append(_check(
            "live_table_untouched",
            initial_tables is not None and initial_tables == final_tables,
            {
                "reason": "the recipe only READS the seeded table; the live snapshot "
                          "must be identical before and after the run",
                "initial_tables": initial_tables,
                "final_tables": final_tables,
            },
        ))
        cleanup = (details.get("cleanup_response") or {}).get("snowflake_live") or {}
        checks.append(_check(
            "cleanup_dropped_registered_table",
            bool(cleanup.get("ok")) and TABLE_KEY in (cleanup.get("dropped_tables") or []),
            {
                "reason": "the runner must drop the seeded live table in its finally",
                "expected_table": TABLE_KEY,
                "cleanup_response": cleanup,
            },
        ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "recipe 94382842 has no stop steps", "stop_rows": stop_rows},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}




