_SNAPSHOT_TABLE_120183307 = "edw_db.workato_usage_intermediate.accounts_snapshot"


def _multiset_pairs_120183307(rows: Any) -> list[tuple[str, str, str]]:
    """Order-insensitive comparison key: (col10, col2, full-sorted-json)."""
    import json as _json

    out: list[tuple[str, str, str]] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            out.append(("", "", _json.dumps(row, default=str)))
            continue
        public = {key: value for key, value in row.items() if not str(key).startswith("_")}
        out.append(
            (
                str(public.get("col10") or ""),
                str(public.get("col2") or ""),
                _json.dumps(public, sort_keys=True, default=str),
            )
        )
    return sorted(out)


def verify_120183307(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
