    expected_col1 = (expect.get("add_entry_parameters") or {}).get("col1")
    if expect.get("sql_row_count"):
        checks.append(_check(
            "snowflake_rows_all_carry_max_entry_date",
            bool(returned_rows)
            and all(
                isinstance(row, dict) and str(row.get("entry_date")) == str(expected_col1)
                for row in returned_rows
            ),
            {"expected_entry_date": expected_col1, "actual_rows": returned_rows},
        ))

    # --- branch discriminator: WHICH batch step traced ---
    batch_step_as = str(expect.get("batch_step_as") or "")
    batch_rows = by_as.get(batch_step_as) or []
