        checks.append(_check(
            "where_clause_arm_matches_exactly",
            where_clause == expect.get("where_clause"),
            {
                "reason": "the 3-arm if/elsif/else must pick the pinned identity arm "
                          "(EMPLOYEE_ID when present, else APP_USER_ID, else USERNAME) "
                          "with the row values interpolated verbatim",
                "expected_where": expect.get("where_clause"),
                "actual_where": where_clause,
            },
        ))
