def _case_field_126727318(row: dict[str, Any], field: str) -> Any:
    if field in row:
        return row[field]
    lower = str(field).lower()
    if lower in row:
        return row[lower]
    upper = str(field).upper()
    if upper in row:
        return row[upper]
    return None


def _final_table_checks_126727318(
    expected_tables: Any,
    final_snapshot: dict[str, Any],
) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    snapshot_tables = (final_snapshot.get("snowflake") or {}).get("tables") or {}
    if not isinstance(expected_tables, dict) or not expected_tables:
        checks.append(_check(
            "expect_final_snowflake_tables_present",
            False,
            {"expected_tables": expected_tables},
        ))
        return checks
    for table_key, spec in expected_tables.items():
        spec = spec if isinstance(spec, dict) else {}
        rows = snapshot_tables.get(str(table_key))
        checks.append(_check(
            f"final_{table_key}_row_count_matches",
            isinstance(rows, list) and len(rows) == spec.get("count"),
            {"table": table_key, "expected_count": spec.get("count"),
             "actual_count": len(rows) if isinstance(rows, list) else None},
        ))
        match_fields = spec.get("match_fields") if isinstance(spec.get("match_fields"), list) else []
        for row_idx, expected_row in enumerate(spec.get("rows") or []):
            if not isinstance(expected_row, dict) or not match_fields:
                checks.append(_check(
                    f"final_{table_key}_expected_row_{row_idx}_well_formed",
                    False,
                    {"expected_row": expected_row, "match_fields": match_fields},
                ))
                continue
            matches = [
                row for row in (rows if isinstance(rows, list) else [])
                if isinstance(row, dict)
                and all(
                    str(_case_field_126727318(row, field)) == str(expected_row.get(field))
                    for field in match_fields
                )
            ]
            checks.append(_check(
                f"final_{table_key}_row_{row_idx}_matches_exactly_once",
                len(matches) == 1
                and all(
                    str(_case_field_126727318(matches[0], key)) == str(value)
                    for key, value in expected_row.items()
                ),
                {"table": table_key, "expected_row": expected_row,
                 "match_fields": match_fields, "matches": matches},
            ))
    return checks


