    upsert_result = (upsert_calls[0].get("result") or {}) if upsert_calls else {}
    checks.append(_check(
        "upsert_created_updated_counts_match",
        upsert_result.get("created") == expect.get("upsert_created")
        and upsert_result.get("updated") == expect.get("upsert_updated"),
        {
            "reason": "TRUNCATE empties the table first, so every row INSERTS; a nonzero "
                      "updated count means the truncate did not run (or ran after)",
            "expected_created": expect.get("upsert_created"),
            "expected_updated": expect.get("upsert_updated"),
            "actual_result": upsert_result,
        },
    ))

    # Final Snowflake state: EXACT table equality (normalized lowercase keys,
    # sorted by row_number) -- count equality proves the stale rows are gone.
    def _norm_rows(rows: Any) -> list[dict[str, Any]]:
        out = []
        for row in rows or []:
            if isinstance(row, dict):
                out.append({str(key).lower(): value for key, value in row.items()})
        return sorted(out, key=lambda row: (str(row.get("row_number")), str(row.get("user"))))

    actual_final = _norm_rows(
        ((final_snapshot.get("snowflake") or {}).get("tables") or {}).get(table_name)
    )
