def verify_118340691(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    tool_calls = result.get("tool_calls") or []
    checks = list(replay.get("checks") or [])

    required_keys = (
        "executed_action_count",
        "tools",
        "tool_expectations",
        "branch",
        "stopped",
        "return_value",
        "query_sql",
        "query_rows",
        "limit_items",
        "logger_message",
    )
    missing = [key for key in required_keys if key not in expect]
    checks.append(_check(
        "expect_carries_all_118340691_ground_truth_keys",
        not missing,
        {"missing": missing, "expect_keys": sorted(expect.keys())},
    ))
    if missing:
        return {"ok": False, "checks": checks}

    branch = expect.get("branch")
    checks.append(_check(
        "expect_branch_is_known",
        branch in (
            "all_match_success",
            "limit_mismatch_stop",
            "features_missing_output_bigger",
            "features_missing_input_bigger",
            "input_limit_absent_skip",
            "equal_size_swap_stop",
        ),
        {"branch": branch},
    ))

    # All five query_list steps, in step order, with RESOLVED sql byte-exact
    # and their projected rows pinned.
    step_order = ["b6591ebf", "eeaeaf5a", "19fafc56", "902227bd", "5651eeb1"]
    query_trace = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_smart_list.query_list"
    ]
    actual_ids = [str(row.get("as") or "") for row in query_trace]
    checks.append(_check(
        "query_list_steps_ran_in_order",
        actual_ids == step_order,
        {"expected": step_order, "actual": actual_ids},
    ))
    expected_sql = expect.get("query_sql") if isinstance(expect.get("query_sql"), dict) else {}
    expected_rows = expect.get("query_rows") if isinstance(expect.get("query_rows"), dict) else {}
    for row in query_trace:
        step_as = str(row.get("as") or "")
        args_sql = (row.get("args") or {}).get("sql")
        result_rows = (row.get("result") or {}).get("rows")
        checks.append(_check(
            f"query_{step_as}_sql_matches_exactly",
            args_sql == expected_sql.get(step_as),
            {
                "reason": "the resolved sql pins the concat/format_map INSERT bodies and the "
                          "size-picked NOT IN direction byte-exact",
                "expected_sql": expected_sql.get(step_as),
                "actual_sql": args_sql,
            },
        ))
        checks.append(_check(
            f"query_{step_as}_rows_match_exactly",
            result_rows == expected_rows.get(step_as),
            {
                "reason": "INSERT outputs are the inserted rows (their SIZE picks the "
                          "direction); 5651eeb1 rows are the reported missing products",
                "expected_rows": expected_rows.get(step_as),
                "actual_rows": result_rows,
            },
        ))

    # Declared 'Limits Matching' list byte-exact (skip-dropped keys included).
    declare_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.declare_list"
    ]
    declared_items = ((declare_rows[0].get("result") or {}).get("list_items")) if declare_rows else None
    checks.append(_check(
        "limit_items_match_engine_canonical_rendering_exactly",
        len(declare_rows) == 1 and declared_items == expect.get("limit_items"),
        {
            "reason": "skip-valued match_result fields are DROPPED from the item (Workato "
                      "'not supplied'); mismatch items carry the verbatim joined message",
            "expected_items": expect.get("limit_items"),
            "actual_items": declared_items,
        },
    ))

    # Logger rendering byte-exact.
    log_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.log_message"
    ]
    actual_messages = [(row.get("args") or {}).get("message") for row in log_rows]
    checks.append(_check(
        "logger_message_matches_exactly",
        actual_messages == [expect.get("logger_message")],
        {
            "reason": "pluck('match_result').compact.join('; ').presence or 'Schema matched'",
            "expected": [expect.get("logger_message")],
            "actual": actual_messages,
        },
    ))

    # Stop-gate semantics.
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "stop_outcome_matches_expected",
        bool(stop_rows) is bool(expect.get("stopped")),
        {"expected_stopped": expect.get("stopped"), "stop_rows": stop_rows},
    ))
    if expect.get("stopped"):
        checks.append(_check(
            "stopped_exactly_at_step_10_marker",
            [(row.get("number"), row.get("as")) for row in stop_rows] == [(10, "8657dddc")],
            {"stop_rows": stop_rows},
        ))
        checks.append(_check(
            "stopped_run_called_no_registry_tools",
            not tool_calls,
            {"tool_calls": tool_calls},
        ))

    checks.append(_check(
        "return_value_matches_expected",
        raw_execution.get("return_value") == expect.get("return_value"),
        {"expected": expect.get("return_value"), "actual": raw_execution.get("return_value")},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}




def verify_111834972(result: dict[str, Any]) -> dict[str, Any]:
    ANON_TARGET = (
        "<anon>aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee</anon>:<anon>b1a2c3d4</anon>:connection_cell"
    )
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    checks = list(replay.get("checks") or [])

    required_keys = (
        "executed_action_count",
        "tools",
        "tool_expectations",
        "matched_row_count",
        "logger_message",
        "connection_cell_updates",
        "loop_note_writes",
        "final_connection_value",
        "return_value",
        "initial_sheet_rows",
        "final_sheet_rows",
    )
    missing = [key for key in required_keys if key not in expect]
    checks.append(_check(
        "expect_carries_all_111834972_ground_truth_keys",
        not missing,
        {"missing": missing, "expect_keys": sorted(expect.keys())},
    ))
    if missing:
        return {"ok": False, "checks": checks}

    # Logger pins the match count as a string.
    log_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.log_message"
    ]
    actual_messages = [(row.get("args") or {}).get("message") for row in log_rows]
    checks.append(_check(
        "logger_message_is_stringified_match_count",
        actual_messages == [expect.get("logger_message")],
        {"expected": [expect.get("logger_message")], "actual": actual_messages},
    ))

    # Accumulation: verbatim anon target on EVERY write + byte-exact states.
    var_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.update_variables"
    ]
    actual_targets = [(row.get("args") or {}).get("name") for row in var_rows]
    checks.append(_check(
        "every_accumulation_write_targets_the_verbatim_anon_tag",
        bool(var_rows) and all(target == ANON_TARGET for target in actual_targets),
        {
            "reason": "the schema-only declare owns no field, so the store must live under "
                      "the tagged id the read pills share (owners==0 verbatim fallback)",
            "expected_target": ANON_TARGET,
            "actual_targets": actual_targets,
        },
    ))
    actual_updates = [(row.get("result") or {}).get("connection_cell") for row in var_rows]
    checks.append(_check(
        "connection_cell_accumulation_matches_exactly",
        actual_updates == expect.get("connection_cell_updates"),
        {
            "reason": "iteration-1 reads the never-written line ('' like the nil declare) -> "
                      "every state carries the faithful LEADING newline",
            "expected": expect.get("connection_cell_updates"),
            "actual": actual_updates,
        },
    ))

    # Loop note writes: [row_number, raw-int index] in search order; the final
    # write targets the loop-index-0 row with the accumulated multi-line cell.
    update_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "google_sheets.update_row_v4_new"
    ]
    loop_rows = update_rows[:-1]
    actual_notes = [
        [(row.get("args") or {}).get("row_number"), ((row.get("args") or {}).get("data") or {}).get("Recipe Note")]
        for row in loop_rows
    ]
    checks.append(_check(
        "loop_note_writes_match_search_order_with_raw_int_indexes",
        actual_notes == expect.get("loop_note_writes")
        and all(str(row.get("as") or "") == "c5c84e5b" for row in loop_rows),
        {
            "expected": expect.get("loop_note_writes"),
            "actual": actual_notes,
            "loop_step_ids": [row.get("as") for row in loop_rows],
        },
    ))
    final_row = update_rows[-1] if update_rows else {}
    final_args = final_row.get("args") or {}
    expected_notes = expect.get("loop_note_writes") or []
    index0_row_number = expected_notes[0][0] if expected_notes and isinstance(expected_notes[0], list) else None
    checks.append(_check(
        "final_write_rolls_up_onto_the_index_0_row",
        str(final_row.get("as") or "") == "ef42b08e"
        and final_args.get("row_number") == index0_row_number
        and final_args.get("data")
        == {"Connection": expect.get("final_connection_value"), "Recipe Note": "KEEP"},
        {
            "reason": "step-8 search (Recipe Note '0' AND URL) selects exactly the loop-"
                      "index-0 row; the write label-decodes into the real columns",
            "expected_row_number": index0_row_number,
            "expected_data": {
                "Connection": expect.get("final_connection_value"),
                "Recipe Note": "KEEP",
            },
            "actual_args": final_args,
        },
    ))

    # Full tab transition byte-exact (decoys untouched).
    def _rows(snapshot: dict[str, Any]) -> Any:
        return (snapshot.get("google_sheets") or {}).get("rows")

    checks.append(_check(
        "initial_sheet_rows_match_exactly",
        _rows(initial_snapshot) == expect.get("initial_sheet_rows"),
        {"expected": expect.get("initial_sheet_rows"), "actual": _rows(initial_snapshot)},
    ))
    checks.append(_check(
        "final_sheet_rows_match_exactly",
        _rows(final_snapshot) == expect.get("final_sheet_rows"),
        {
            "reason": "matched rows carry their loop-index Recipe Notes except the index-0 "
                      "row (accumulated multi-line Connection + 'KEEP'); decoys are "
                      "byte-identical to the seed",
            "expected": expect.get("final_sheet_rows"),
            "actual": _rows(final_snapshot),
        },
    ))

    checks.append(_check(
        "return_value_matches_expected",
        raw_execution.get("return_value") == expect.get("return_value"),
        {"expected": expect.get("return_value"), "actual": raw_execution.get("return_value")},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}




def verify_121951507(result: dict[str, Any]) -> dict[str, Any]:
    GET_USER_STEP = "ff6ae1d3"
    SEARCH_STEP = "2a70f21a"
    ADMIN_HOME_STEP = "2c4d9486"
    DEFAULT_HOME_STEP = "271782f8"
    DEAD_TOP_STEP = "49391591"
    DEAD_ELSE_STEP = "98084ab8"
    TABLE_ID = "3770006"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []

    required = ("outcome", "member_email", "matched_entry_count", "home_step", "home_blocks")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 121951507 variant must pin outcome, member_email, "
                          "matched_entry_count, home_step and home_blocks",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    outcome = expect.get("outcome")
    user = str((trigger.get("app_home_opened") or {}).get("user") or "")

    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_tool_sequence_is_lookup_search_publish",
        outcome in ("admin_home", "default_home")
        and trace_tools == [
            "slack_bot.get_user_by_email",
            "lookup_table.search_entries",
            "slack_bot.open_bot_app_home",
        ],
        {
            "reason": "every reachable path runs LIVE users.info, then the mock col3 "
                      "search, then exactly one LIVE views.publish",
            "outcome": outcome,
            "actual_trace": trace_tools,
        },
    ))

    user_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.get_user_by_email"
    ]
    user_result = (user_rows[0].get("result") or {}) if user_rows else {}
    live_email = ((user_result.get("profile") or {}) if isinstance(user_result.get("profile"), dict) else {}).get("email")
    checks.append(_check(
        "live_users_info_resolved_member_email",
        len(user_rows) == 1
        and str(user_rows[0].get("as") or "") == GET_USER_STEP
        and (user_rows[0].get("args") or {}) == {"id": user}
        and bool(user_result.get("ok"))
        and live_email == expect.get("member_email"),
        {
            "reason": "get_user_by_email must hit LIVE users.info with the trigger "
                      "user id and the returned profile.email must be the pinned "
                      "live member email (U0B91BSRGF8 <-> jamie.lee@corp.example)",
            "expected_email": expect.get("member_email"),
            "actual_rows": user_rows,
        },
    ))

    search_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "lookup_table.search_entries"
    ]
    search_args = (search_rows[0].get("args") or {}) if search_rows else {}
    search_entries = (search_rows[0].get("result") or {}).get("entries") if search_rows else None
    checks.append(_check(
        "search_keyed_on_live_email_with_pinned_count",
        len(search_rows) == 1
        and str(search_rows[0].get("as") or "") == SEARCH_STEP
        and search_args == {
            "lookup_table_id": TABLE_ID,
            "parameters": {"col3": expect.get("member_email")},
        }
        and (search_args.get("parameters") or {}).get("col3") == live_email
        and isinstance(search_entries, list)
        and len(search_entries) == expect.get("matched_entry_count")
        and all(
            isinstance(entry, dict)
            and isinstance(entry.get("entry"), dict)
            and entry.get("col3") == entry["entry"].get("col3") == expect.get("member_email")
            for entry in search_entries
        ),
        {
            "reason": "one search on table 3770006 (twin guard: 119575741 uses "
                      "3808792) whose col3 parameter is the LIVE-returned profile "
                      "email; the entry count proves the exact-match against decoys "
                      "and entries carry both flat colN and nested entry.colN",
            "expected_count": expect.get("matched_entry_count"),
            "expected_email": expect.get("member_email"),
            "actual_args": search_args,
            "actual_count": len(search_entries) if isinstance(search_entries, list) else None,
        },
    ))

    expected_home_step = ADMIN_HOME_STEP if outcome == "admin_home" else DEFAULT_HOME_STEP
    other_home_step = DEFAULT_HOME_STEP if outcome == "admin_home" else ADMIN_HOME_STEP
    matched = expect.get("matched_entry_count")
    checks.append(_check(
        "outcome_consistent_with_matched_entry_count",
        expect.get("home_step") == expected_home_step
        and (
            (outcome == "admin_home" and isinstance(matched, int) and matched >= 1)
            or (outcome == "default_home" and matched == 0)
        ),
        {
            "reason": "IF pivots on entries size > 0: any positive count (1 or 2) "
                      "is the admin branch, zero is the default branch",
            "outcome": outcome,
            "matched_entry_count": matched,
            "home_step": expect.get("home_step"),
        },
    ))

    home_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.open_bot_app_home"
    ]
    home_args = (home_rows[0].get("args") or {}) if home_rows else {}
    checks.append(_check(
        "home_publish_matches_branch_verbatim",
        len(home_rows) == 1
        and str(home_rows[0].get("as") or "") == expected_home_step
        and home_args.get("user_id") == user
        and home_args.get("view") == {"blocks": expect.get("home_blocks")}
        and all(str(row.get("as") or "") != other_home_step for row in trace),
        {
            "reason": "exactly one publish from the branch-owning step (16-block "
                      "admin 2c4d9486 vs 11-block default 271782f8), targeting the "
                      "trigger user with the pinned RAW Workato block payload; the "
                      "other branch's step must be absent",
            "expected_step": expected_home_step,
            "expected_view": {"blocks": expect.get("home_blocks")},
            "actual_rows": home_rows,
        },
    ))
    home_result = (home_rows[0].get("result") or {}) if home_rows else {}
    checks.append(_check(
        "home_publish_delivered_live",
        bool(home_result.get("ok")),
        {
            "reason": "the live views.publish response must be ok (post-fix the "
                      "image/button/fields blocks all translate: 16/16 and 11/11)",
            "actual_result": home_result,
        },
    ))

    dead_top_rows = [row for row in trace if isinstance(row, dict) and str(row.get("as") or "") == DEAD_TOP_STEP]
    dead_else_rows = [row for row in trace if isinstance(row, dict) and str(row.get("as") or "") == DEAD_ELSE_STEP]
    expected_dead_else = 1 if outcome == "default_home" else 0
    checks.append(_check(
        "dead_steps_stay_skipped",
        len(dead_top_rows) == 1
        and dead_top_rows[0].get("skipped") is True
        and not dead_top_rows[0].get("tool")
        and len(dead_else_rows) == expected_dead_else
        and all(row.get("skipped") is True and not row.get("tool") for row in dead_else_rows),
        {
            "reason": "skip:true 49391591 is traced skipped on every run; skip:true "
                      "98084ab8 (absent in the 119575741 twin) is traced skipped "
                      "ONLY when the ELSE branch executes",
            "expected_dead_else_rows": expected_dead_else,
            "dead_top_rows": dead_top_rows,
            "dead_else_rows": dead_else_rows,
        },
    ))

    initial = details.get("initial_snapshot")
    final = details.get("final_snapshot")
    checks.append(_check(
        "lookup_table_untouched",
        isinstance(initial, dict) and initial == final and initial != {},
        {
            "reason": "the recipe only READS table 3770006; the mock snapshot must "
                      "be identical before and after the run",
            "initial_snapshot": initial,
            "final_snapshot": final,
        },
    ))
    return {"ok": _checks_ok(checks), "checks": checks}






