def _multiset_rows_103520604(rows: Any) -> list[tuple[str, str, str]]:
    """Order-insensitive comparison key: (col10, col2, full-sorted-json)."""
    import json as _json

    out: list[tuple[str, str, str]] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            out.append(("", "", _json.dumps(row, default=str)))
            continue
        public = {key: value for key, value in row.items() if not str(key).startswith("_")}
        out.append(
            (
                str(public.get("col10") or ""),
                str(public.get("col2") or ""),
                _json.dumps(public, sort_keys=True, default=str),
            )
        )
    return sorted(out)


