def verify_88708198(result: dict[str, Any]) -> dict[str, Any]:
    UPDATE_TOOL = "salesforce.update_record"
    REPLY_TOOL = "workato_service.send_reply"
    CATCH_STEP = "2d7b3539"
    SOBJECT = "Campaign_Activity__c"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}

    required = ("branch", "updated_fields", "absent_fields", "reply", "untouched_fields", "catch_message")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 88708198 variant must pin branch, updated_fields, "
                          "absent_fields, reply, untouched_fields and catch_message",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    branch = str(expect.get("branch") or "")
    is_catch = branch == "catch_error_reply"

    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    expected_trace = [REPLY_TOOL] if is_catch else [UPDATE_TOOL, REPLY_TOOL]
    checks.append(_check(
        "trace_tool_sequence_matches_branch",
        trace_tools == expected_trace,
        {
            "reason": "success branches run update -> success reply; the catch branch "
                      "runs ONLY the error reply (the refused update never traces)",
            "expected_trace": expected_trace,
            "actual_trace": trace_tools,
        },
    ))

    def _snapshot_fields(snapshot: Any) -> dict[str, Any]:
        salesforce = (snapshot or {}).get("salesforce") if isinstance(snapshot, dict) else {}
        records = salesforce.get("records") if isinstance(salesforce, dict) else []
        owned = [
            row for row in records or []
            if isinstance(row, dict) and not row.get("read_only")
            and str(row.get("sobject") or "") == SOBJECT
        ]
        if len(owned) != 1:
            return {}
        fields = owned[0].get("fields")
        return fields if isinstance(fields, dict) else {}

    def _same_field_value(actual: Any, expected: Any) -> bool:
        if isinstance(actual, bool) or isinstance(expected, bool):
            return str(actual).lower() == str(expected).lower()
        return actual == expected

    initial_fields = _snapshot_fields(details.get("initial_snapshot"))
    final_fields = _snapshot_fields(details.get("final_snapshot"))
    checks.append(_check(
        "seeded_record_present_in_both_snapshots",
        bool(initial_fields) and bool(final_fields),
        {
            "reason": "every variant seeds exactly one owned Campaign_Activity__c "
                      "record and both snapshots must read it back",
            "initial_fields": initial_fields,
            "final_fields": final_fields,
        },
    ))

    update_rows = [row for row in trace if isinstance(row, dict) and row.get("tool") == UPDATE_TOOL]
    reply_rows = [row for row in trace if isinstance(row, dict) and row.get("tool") == REPLY_TOOL]
    if is_catch:
        checks.append(_check(
            "catch_no_update_traced",
            not update_rows and expect.get("updated_fields") is None,
            {
                "reason": "the ownership refusal fires before any live write; no "
                          "update row may trace and updated_fields pins null",
                "actual_update_rows": update_rows,
            },
        ))
        catch_payload = step_outputs.get(CATCH_STEP)
        catch_message = catch_payload.get("message") if isinstance(catch_payload, dict) else None
        checks.append(_check(
            "catch_message_is_deterministic_refusal",
            catch_message == expect.get("catch_message")
            and str(expect.get("catch_message") or "").startswith(
                "refusing to update non-owned Salesforce record"
            ),
            {
                "reason": "the catch payload must carry the exact OwnedSalesforce "
                          "refusal text (deterministic, no live write happened)",
                "expected_message": expect.get("catch_message"),
                "actual_payload": catch_payload,
            },
        ))
        checks.append(_check(
            "catch_seeded_record_untouched",
            bool(initial_fields) and initial_fields == final_fields,
            {
                "reason": "the refused update must leave the seeded record byte-"
                          "identical between snapshots",
                "initial_fields": initial_fields,
                "final_fields": final_fields,
            },
        ))
    else:
        expected_fields = expect.get("updated_fields")
        update_args = (update_rows[0].get("args") or {}) if update_rows else {}
        actual_fields = update_args.get("fields") if isinstance(update_args.get("fields"), dict) else {}
        checks.append(_check(
            "update_fields_match_exactly",
            len(update_rows) == 1
            and isinstance(expected_fields, dict)
            and actual_fields == expected_fields
            and update_args.get("sobject") == SOBJECT,
            {
                "reason": "exactly one live update whose fields equal the guard-"
                          "surviving columns EXACTLY (exact equality is what proves "
                          "the SKIP guards dropped everything else)",
                "expected_fields": expected_fields,
                "actual_args": update_args,
            },
        ))
        absent = [
            field for field in expect.get("absent_fields") or []
            if field in actual_fields
        ]
        checks.append(_check(
            "skipped_columns_absent_from_update",
            not absent,
            {
                "reason": "every guard that evaluated SKIP must have dropped its "
                          "column from the live update args",
                "expected_absent": expect.get("absent_fields"),
                "leaked": absent,
            },
        ))
        update_id = str(update_args.get("id") or "")
        initial_id_ok = bool(update_id) and any(
            isinstance(row, dict) and str(row.get("id") or "") == update_id
            for row in ((details.get("initial_snapshot") or {}).get("salesforce") or {}).get("records") or []
        )
        checks.append(_check(
            "update_targeted_seeded_record",
            initial_id_ok,
            {
                "reason": "the request id token must have resolved to the seeded "
                          "live record id",
                "update_id": update_id,
                "initial_snapshot": details.get("initial_snapshot"),
            },
        ))
        mismatched_updates = {
            field: final_fields.get(field)
            for field, value in (expected_fields or {}).items()
            if not _same_field_value(final_fields.get(field), value)
        }
        checks.append(_check(
            "final_snapshot_carries_updated_values",
            bool(final_fields) and not mismatched_updates,
            {
                "reason": "the live read-back must show every updated column value "
                          "(boolean checkbox compared case-insensitively)",
                "expected_fields": expected_fields,
                "mismatched": mismatched_updates,
                "final_fields": final_fields,
            },
        ))
    untouched = expect.get("untouched_fields")
    if isinstance(untouched, dict) and untouched:
        stale = {
            field: final_fields.get(field)
            for field, value in untouched.items()
            if not _same_field_value(final_fields.get(field), value)
        }
        checks.append(_check(
            "untouched_seed_values_persist",
            not stale,
            {
                "reason": "columns whose guards skipped (or the whole record on the "
                          "catch branch) must keep their seeded live values - a "
                          "blank-string request value must NOT clear them",
                "expected_untouched": untouched,
                "mismatched": stale,
                "final_fields": final_fields,
            },
        ))

    reply_args = (reply_rows[-1].get("args") or {}) if reply_rows else {}
    checks.append(_check(
        "final_reply_args_match",
        len(reply_rows) == 1 and reply_args == expect.get("reply"),
        {
            "reason": "exactly one send_reply; success echoes the request id in "
                      "reply.sfdc_campaign_activity_id, the catch reply carries "
                      "reply_type error + the refusal message",
            "expected_reply": expect.get("reply"),
            "actual_rows": reply_rows,
        },
    ))
    checks.append(_check(
        "return_value_is_reply",
        raw_execution.get("return_value") == expect.get("reply"),
        {
            "reason": "send_reply records the recipe's return value verbatim",
            "expected": expect.get("reply"),
            "actual": raw_execution.get("return_value"),
        },
    ))

