_LISTAGG_SET_COLUMNS_130550781 = {"BIZ_CRITICAL_APP_NAMES", "DISPLAY_OUTPUT_TOP_APPS"}


def _cell_matches_130550781(column: str, actual: Any, expected: Any) -> bool:
    if column in _LISTAGG_SET_COLUMNS_130550781:
        if not isinstance(actual, str) or not isinstance(expected, str):
            return actual == expected
        return sorted(part for part in actual.split(",")) == sorted(
            part for part in expected.split(",")
        )
    return actual == expected


def _snowflake_ctas_table_checks_130550781(
    expected_tables: Any,
    final_snapshot: dict[str, Any],
) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    snapshot_tables = (final_snapshot.get("snowflake") or {}).get("tables") or {}
    if not isinstance(expected_tables, dict) or not expected_tables:
        checks.append(_check(
            "expect_final_snowflake_tables_present",
            False,
            {"expected_tables": expected_tables},
        ))
        return checks
    for table_key, spec in expected_tables.items():
        spec = spec if isinstance(spec, dict) else {}
        rows = snapshot_tables.get(str(table_key))
        expected_count = spec.get("count")
