def _canonical_rows_121086244(rows: Any) -> list[tuple]:
    out = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            out.append((("__malformed__", str(row)),))
            continue
        out.append(tuple(sorted(
            (str(key), str(value))
            for key, value in row.items()
            if str(key) != "_row_id"
        )))
    return sorted(out)


