def verify_108516287(result: dict[str, Any]) -> dict[str, Any]:
    SEARCH_TOOL = "snowflake.search_rows_sql"
    RESPONSE_TOOL = "workato_api_platform.return_response"
    CATCH_STEP = "c96801ed"
    RECIPE_DIM = "product.workato_usage.recipe_dim"
    WORKSPACE_DIM = "product.workato_usage.workspace_dim"
    WORKSPACE_IDS_PILL = (
        "#{_dp('{\"pill_type\":\"output\",\"provider\":\"workato_api_platform\","
        "\"line\":\"458af9a1\",\"path\":[\"request\", \"workspace_ids\"]}')}"
    )
    ACCOUNT_ID_PILL = (
        "#{_dp('{\"pill_type\":\"output\",\"provider\":\"workato_api_platform\","
        "\"line\":\"458af9a1\",\"path\":[\"request\", \"account_id\"]}')}"
    )
    RAW_SQL_TEMPLATE = (
        "select \nLISTAGG(distinct wd.workspace_name, ', ') workspaces,\n"
        "count_if(rd.running) running,\n"
        "count_if(rd.is_callable or rd.is_function) function_recipe,\n"
        "count_if(rd.HAS_WORKBOT) HAS_WORKBOT,\n"
        "count_if(rd.is_billable) is_billable,\n"
        "count_if(rd.uses_custom_connector) uses_custom_connector,\n"
        "count_if(rd.USES_OPA) USES_OPA,\n"
        "count_if(rd.is_workbot) is_workbot,\n"
        "count_if(rd.is_etl) is_etl,\n"
        "count_if(rd.IS_REVERSE_ETL) IS_REVERSE_ETL,\n"
        "count_if(rd.is_ai) is_ai\n"
        "from product.workato_usage.recipe_dim rd\n"
        "left join product.workato_usage.workspace_dim wd on wd.workspace_id = rd.user_id\n"
        "where rd.is_latest\nand rd.running\nand wd.is_latest\nand not wd.is_deleted\n"
        "and wd.is_paid_workspace\nand not wd.is_internal\n"
        "and wd.workspace_id in (" + WORKSPACE_IDS_PILL + ")\n"
        "and wd.sales_account_id = '" + ACCOUNT_ID_PILL + "'"
    )
    COUNT_KEYS = (
        "running",
        "function_recipe",
        "has_workbot",
        "is_billable",
        "uses_custom_connector",
        "uses_opa",
        "is_workbot",
        "is_etl",
        "is_reverse_etl",
        "is_ai",
    )
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup = (details.get("cleanup_response") or {}).get("snowflake_live")
    request = ((details.get("trigger") or {}).get("request") or {})
    account_id = str(request.get("account_id") or "")
    workspace_ids_text = str(request.get("workspace_ids") or "")

    required = ("outcome", "http_status_code", "response", "sql_row_count")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 108516287 variant must pin outcome, "
                          "http_status_code, response and sql_row_count",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    outcome = expect.get("outcome")

    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    expected_trace = {
        "aggregates_200": [SEARCH_TOOL, RESPONSE_TOOL],
        "zero_counts_200": [SEARCH_TOOL, RESPONSE_TOOL],
        "catch_500": [RESPONSE_TOOL],
    }.get(str(outcome))
    checks.append(_check(
        "trace_tool_sequence_matches_outcome",
        expected_trace is not None and trace_tools == expected_trace,
        {
            "reason": "data variants run search -> 200 response; the forced catch "
                      "raises BEFORE the snowflake adapter so only the bodyless 500 "
                      "response traces",
            "expected_trace": expected_trace,
            "actual_trace": trace_tools,
        },
    ))

    response_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == RESPONSE_TOOL
    ]
    response_result = (response_rows[0].get("result") or {}) if response_rows else {}
    checks.append(_check(
        "response_matches_pinned_object_exactly",
        len(response_rows) == 1
        and response_result.get("http_status_code") == expect.get("http_status_code")
        and response_result.get("response") == expect.get("response")
        and raw_execution.get("return_value") == expect.get("response"),
        {
            "reason": "the pinned response object (native-int counts + single-name "
                      "workspaces when matched, LIVE all-NULL counts + '' workspaces "
                      "on zero-match, EXACTLY {} on the bodyless 500) must equal both "
                      "the traced response and the job return_value",
            "expected_status": expect.get("http_status_code"),
            "expected_response": expect.get("response"),
            "actual_result": response_result,
            "actual_return_value": raw_execution.get("return_value"),
        },
    ))

    search_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == SEARCH_TOOL
    ]
    if outcome == "catch_500":
        checks.append(_check(
            "catch_never_reached_snowflake_and_owns_no_live_state",
            not search_rows
            and expect.get("sql_row_count") is None
            and expect.get("response") == {}
            and initial_snapshot == {}
            and final_snapshot == {}
            and cleanup is None,
            {
                "reason": "the forced error fires before the adapter: no snowflake "
                          "trace row, a BODYLESS {} 500, no seeded live table, "
                          "nothing to snapshot or clean up",
                "actual_search_rows": search_rows,
                "initial_snapshot": initial_snapshot,
                "final_snapshot": final_snapshot,
                "cleanup_response": cleanup,
            },
        ))
        catch_payload = step_outputs.get(CATCH_STEP)
        message = catch_payload.get("message") if isinstance(catch_payload, dict) else None
        checks.append(_check(
            "catch_message_matches_forced_error",
            bool(message) and message == expect.get("catch_message"),
            {
                "reason": "the c96801ed catch payload records the forced snowflake "
                          "error verbatim (the 500 body itself is empty)",
                "expected_message": expect.get("catch_message"),
                "actual_payload": catch_payload,
            },
        ))
    else:
        expected_sql = RAW_SQL_TEMPLATE.replace(
            WORKSPACE_IDS_PILL, workspace_ids_text
        ).replace(ACCOUNT_ID_PILL, account_id)
        search_args = (search_rows[0].get("args") or {}) if search_rows else {}
        search_result = (search_rows[0].get("result") or {}) if search_rows else {}
        checks.append(_check(
            "search_args_pinned_verbatim",
            len(search_rows) == 1
            and search_args.get("sql") == expected_sql
            and search_args.get("limit") == 1
            and search_args.get("offset") == 0
            and search_args.get("parameters") == {},
            {
                "reason": "exactly one live search whose SQL TEXT carries the "
                          "trigger's raw IN-list and quoted account_id (no bind "
                          "parameters), limit '1', offset '0'",
                "expected_sql": expected_sql,
                "actual_args": search_args,
            },
        ))
        result_rows = search_result.get("rows")
        checks.append(_check(
            "aggregate_returns_exactly_one_row",
            isinstance(result_rows, list)
            and len(result_rows) == 1
            and expect.get("sql_row_count") == 1,
            {
                "reason": "the aggregate SELECT always returns exactly one row — on "
                          "the zero-match path too",
                "expected_count": expect.get("sql_row_count"),
                "actual_rows": result_rows,
            },
        ))
        tables = (initial_snapshot.get("snowflake") or {}).get("tables") or {}
        recipe_rows = tables.get(RECIPE_DIM)
        workspace_rows = tables.get(WORKSPACE_DIM)
        derived: Any = None
        try:
            id_set = {int(part) for part in workspace_ids_text.split(",")}
        except ValueError:
            id_set = None
        if isinstance(recipe_rows, list) and isinstance(workspace_rows, list) and id_set is not None:
            by_id = {
                row.get("workspace_id"): row
                for row in workspace_rows
                if isinstance(row, dict)
            }
            matched: list[dict[str, Any]] = []
            names: set[str] = set()
            for rd in recipe_rows:
                if not isinstance(rd, dict) or not (rd.get("is_latest") and rd.get("running")):
                    continue
                wd = by_id.get(rd.get("user_id"))
                if not isinstance(wd, dict):
                    continue
                if not (
                    wd.get("is_latest")
                    and not wd.get("is_deleted")
                    and wd.get("is_paid_workspace")
                    and not wd.get("is_internal")
                    and wd.get("workspace_id") in id_set
                    and wd.get("sales_account_id") == account_id
                ):
                    continue
                matched.append(rd)
                names.add(str(wd.get("workspace_name")))
            if len(names) <= 1:
                derived = {}
                if not matched:
                    # LIVE zero-match shape (output/108516287/variant_01):
                    # count_if over the empty aggregate input is NULL and
                    # LISTAGG(distinct ...) renders ''.
                    for key in COUNT_KEYS:
                        derived[key] = None
                    derived["workspaces"] = ""
                else:
                    for key in COUNT_KEYS:
                        if key == "function_recipe":
                            derived[key] = sum(
                                1 for rd in matched if rd.get("is_callable") or rd.get("is_function")
                            )
                        else:
                            derived[key] = sum(1 for rd in matched if rd.get(key))
                    derived["workspaces"] = next(iter(names)) if names else None
        checks.append(_check(
            "response_recomputed_from_live_snapshot",
            derived is not None and derived == expect.get("response"),
            {
                "reason": "independent derivation: join on workspace_id == user_id, "
                          "every WHERE arm incl. the raw IN-list and account filter, "
                          "count_if per flag with the OR-composite function_recipe, "
                          "the single-name LISTAGG(distinct) (>1 distinct matched "
                          "name is refused as non-deterministic), and the LIVE "
                          "zero-match shape (all-NULL counts + '' workspaces) must "
                          "reproduce the pinned response",
                "derived": derived,
                "expected_response": expect.get("response"),
                "recipe_rows": recipe_rows,
                "workspace_rows": workspace_rows,
            },
        ))
        initial_tables = (initial_snapshot.get("snowflake") or {}).get("tables")
        final_tables = (final_snapshot.get("snowflake") or {}).get("tables")
        checks.append(_check(
            "live_tables_untouched",
            initial_tables is not None and initial_tables == final_tables,
            {
                "reason": "the recipe only READS the seeded dim tables; the live "
                          "snapshot must be identical before and after the run",
                "initial_tables": initial_tables,
                "final_tables": final_tables,
            },
        ))
        checks.append(_check(
            "cleanup_dropped_registered_tables",
            isinstance(cleanup, dict)
            and bool(cleanup.get("ok"))
            and RECIPE_DIM in (cleanup.get("dropped_tables") or [])
            and WORKSPACE_DIM in (cleanup.get("dropped_tables") or []),
            {
                "reason": "the runner must drop BOTH seeded WORKATO_USAGE dim tables "
                          "(shared with twin 108333874) in its finally",
                "expected_tables": [RECIPE_DIM, WORKSPACE_DIM],
                "cleanup_response": cleanup,
            },
        ))
    return {"ok": _checks_ok(checks), "checks": checks}




