def _multiset_rows_113804593(rows: Any) -> list[tuple[str, str, str]]:
    """Order-insensitive comparison key: (col9, col2, full-sorted-json) over
    public (non-underscore) keys."""
    import json as _json

    out: list[tuple[str, str, str]] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            out.append(("", "", _json.dumps(row, default=str)))
            continue
        public = {key: value for key, value in row.items() if not str(key).startswith("_")}
        out.append(
            (
                str(public.get("col9") or ""),
                str(public.get("col2") or ""),
                _json.dumps(public, sort_keys=True, default=str),
            )
        )
    return sorted(out)


def _qualifying_from_snapshot_113804593(initial_sf: dict[str, Any]) -> list[dict[str, Any]] | None:
    """Re-derive the export FROM the live pre-run snapshot: global
    max(entry_date) AND account_id not in either exclusion table AND
    is_direct AND is_paying. Returns None when the snapshot is unusable."""
    snapshot_rows = initial_sf.get(_SNAPSHOT_TABLE_113804593)
    internal_rows = initial_sf.get(_INTERNAL_TABLE_113804593)
    deleted_rows = initial_sf.get(_DELETED_TABLE_113804593)
    if not isinstance(snapshot_rows, list) or not snapshot_rows:
        return None
    if not isinstance(internal_rows, list) or not isinstance(deleted_rows, list):
        return None
    excluded = {str((row or {}).get("id")) for row in internal_rows if isinstance(row, dict)}
    excluded |= {
        str((row or {}).get("account_id")) for row in deleted_rows if isinstance(row, dict)
    }
    max_date = max(str((row or {}).get("entry_date")) for row in snapshot_rows)
    out: list[dict[str, Any]] = []
    for row in snapshot_rows:
        if not isinstance(row, dict):
            return None
        if (
            str(row.get("entry_date")) == max_date
            and str(row.get("account_id")) not in excluded
            and row.get("is_direct") is True
            and row.get("is_paying") is True
        ):
            out.append(
                {
                    _ALIAS_TO_COL_113804593[alias]: str(row.get(column))
                    for column, alias in _SEED_COLUMN_TO_ALIAS_113804593.items()
                }
            )
    return out


