    if expect.get("case") == "trigger_filter_false":
        # trigger-filter-false arm: the Campaign_Activity__c was created
        # WITHOUT a Browser_Timezone__c (blank fails the root 'present'
        # filter) -> the job never starts and the seeded record is untouched.
        initial_records = [r for r in ((details.get("initial_snapshot") or {}).get("salesforce") or {}).get("records") or []
                           if isinstance(r, dict) and r.get("sobject") == SOBJECT]
        final_records = [r for r in ((details.get("final_snapshot") or {}).get("salesforce") or {}).get("records") or []
                         if isinstance(r, dict) and r.get("sobject") == SOBJECT]
        cleanup_response = (details.get("cleanup_response") or {}).get("salesforce") or {}
        checks = [
            _check("trigger_filter_evaluated_false",
                   raw_execution.get("trigger_filter_matched") is False,
                   {"actual": raw_execution.get("trigger_filter_matched")}),
            _raw_execution_path_check(raw_execution, 0),
            _check("no_tool_calls", not result.get("tool_calls"),
                   {"tool_calls": result.get("tool_calls")}),
            _check("seeded_record_untouched",
                   len(initial_records) == 1 and len(final_records) == 1
                   and (final_records[0].get("fields") or {}) == (initial_records[0].get("fields") or {}),
                   {"initial_records": initial_records, "final_records": final_records}),
            _check("salesforce_cleanup_ok",
                   cleanup_response.get("ok") is True and not cleanup_response.get("leftovers"),
                   {"cleanup_response": cleanup_response}),
        ]
        return {"ok": _checks_ok(checks), "checks": checks}
    replay = _verify_replay_recipe(result)
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup_response = (details.get("cleanup_response") or {}).get("salesforce") or {}
    checks = list(replay.get("checks") or [])

    required = (
        "search_list_size",
        "lookup_entries_count",
        "updated_fields",
        "final_record_fields",
        "record_untouched",
        "steps_absent_from_trace",
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 104943316 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    checks.append(_check(
        "trigger_filter_matched",
        raw_execution.get("trigger_filter_matched") is True,
        {
            "reason": "Browser_Timezone__c is present on every variant payload -- the "
                      "trigger filter always matches",
            "actual": raw_execution.get("trigger_filter_matched"),
        },
    ))

    action_rows = [row for row in trace if isinstance(row, dict) and row.get("tool")]
    by_as: dict[str, list[dict[str, Any]]] = {}
    for row in action_rows:
        by_as.setdefault(str(row.get("as") or ""), []).append(row)

    # --- the seeded benchmark-owned record (exactly one, from the pre-run
