def verify_85944692(result: dict[str, Any]) -> dict[str, Any]:
    import json as _json

    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    tool_calls = result.get("tool_calls") or []
    seed_message = details.get("seed_slack_message") if isinstance(details.get("seed_slack_message"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    branch = expect.get("branch")

    checks.append(_check(
        "expect_branch_is_known",
        branch in ("confirm_replaces_block", "target_mid_message_multi_block", "catch_logs_type_and_message"),
        {"branch": branch},
    ))

    logger_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.log_message"
    ]

    if branch == "catch_logs_type_and_message":
        checks.append(_check(
            "catch_branch_never_reached_slack",
            tool_calls == [],
            {
                "reason": "the forced 74ec3e0a error fires before arg resolution; "
                          "chat.update must never happen and the seeded live message "
                          "stays untouched",
                "tool_calls": tool_calls,
            },
        ))
        logged = [
            ((row.get("args") or {}).get("message")) for row in logger_rows
        ]
        checks.append(_check(
            "catch_logged_pinned_type_and_message",
            logged == [expect.get("log_message")] and bool(expect.get("log_message")),
            {"expected_log_message": expect.get("log_message"), "actual_logged": logged},
        ))
        catch_payload = (raw_execution.get("step_outputs") or {}).get("8471803f")
        checks.append(_check(
            "catch_step_output_pins_type_and_message",
            isinstance(catch_payload, dict)
            and catch_payload.get("type") == "RawRecipeExecutionError"
            and catch_payload.get("message") == expect.get("catch_error")
            and bool(expect.get("catch_error")),
            {"expected_error": expect.get("catch_error"), "actual_payload": catch_payload},
        ))
    else:
        updates = [call for call in tool_calls if call.get("tool") == "slack.update_blocks_by_block_id"]
        checks.append(_check(
            "exactly_one_live_block_update",
            len(updates) == 1 and len(tool_calls) == 1,
            {"tool_calls": [call.get("tool") for call in tool_calls]},
        ))
        update = updates[0] if updates else {}
        args = update.get("args") or {}
        try:
            parsed_message = _json.loads(str(args.get("message_json") or ""))
        except ValueError:
            parsed_message = None
        expected_message = {
            "channel": seed_message.get("channel"),
            "ts": seed_message.get("ts"),
            "text": seed_message.get("text"),
            "blocks": seed_message.get("blocks"),
        }
        checks.append(_check(
            "message_json_is_the_live_seeded_message",
            isinstance(parsed_message, dict)
            and bool(seed_message.get("ts"))
            and parsed_message == expected_message,
            {"expected_message": expected_message, "parsed_message": parsed_message},
        ))
        update_result = update.get("result") or {}
        expected_final = expect.get("final_blocks")
        checks.append(_check(
            "chat_update_pushed_the_pinned_final_blocks",
            isinstance(expected_final, list)
            and bool(expected_final)
            and update_result.get("blocks") == expected_final
            and str(update_result.get("channel")) == str(seed_message.get("channel"))
            and str(update_result.get("ts")) == str(seed_message.get("ts"))
            and bool(update_result.get("ok")),
            {
                "expected_final_blocks": expected_final,
                "actual_result": update_result,
                "seed_message_ts": seed_message.get("ts"),
            },
        ))
        seed_blocks = seed_message.get("blocks") if isinstance(seed_message.get("blocks"), list) else []
        target_id = str(expect.get("target_block_id") or "")
        mismatches = _85944692_in_place_mismatches(seed_blocks, expected_final or [], target_id)
        checks.append(_check(
            "replacement_is_in_place_with_untouched_neighbours",
            bool(target_id) and not mismatches,
            {"target_block_id": target_id, "mismatches": mismatches},
        ))
