def verify_88676643(result: dict[str, Any]) -> dict[str, Any]:
    LOG_TOOL = "workato_runtime.log_message"
    TRY_LOG_AS = "8a8d5d15"
    CATCH_AS = "cdf884c4"
    CATCH_LOG_AS = "71f22ee0"
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}

    required = ("branch", "log_step_as", "log_message", "catch_message")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 88676643 variant must pin branch, log_step_as, "
                          "log_message and catch_message",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    branch = str(expect.get("branch") or "")

    log_rows = [row for row in trace if isinstance(row, dict) and row.get("tool") == LOG_TOOL]
    action_rows = [row for row in trace if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")]
    log_row = log_rows[0] if log_rows else {}
    checks.append(_check(
        "single_log_row_pins_step_and_message",
        len(log_rows) == 1
        and action_rows == log_rows
        and str(log_row.get("as") or "") == str(expect.get("log_step_as") or "")
        and (log_row.get("args") or {}).get("message") == expect.get("log_message")
        and (log_row.get("result") or {}).get("ok") is True
        and (log_row.get("result") or {}).get("message") == expect.get("log_message"),
        {
            "reason": "both branches log exactly once, so the executing step "
                      "as-id (8a8d5d15 try vs 71f22ee0 catch) plus the verbatim "
                      "message is the whole observable ground truth",
            "expected_step_as": expect.get("log_step_as"),
            "expected_message": expect.get("log_message"),
            "actual_log_rows": log_rows,
        },
    ))

    if branch == "happy_log_email":
        user_email = ((trigger.get("context") or {}).get("user_email")
                      if isinstance(trigger.get("context"), dict) else None)
        checks.append(_check(
            "happy_logs_trigger_email_and_catch_never_ran",
            str(expect.get("log_step_as") or "") == TRY_LOG_AS
            and expect.get("catch_message") is None
            and isinstance(user_email, str)
            and user_email != ""
            and (log_row.get("args") or {}).get("message") == user_email
            and CATCH_AS not in step_outputs
            and CATCH_LOG_AS not in step_outputs
            and not any(str(row.get("as") or "") == CATCH_LOG_AS for row in trace),
            {
                "reason": "the message is cross-checked against the seeded "
                          "trigger context.user_email (pill propagation), and the "
                          "catch must leave zero footprint (dead-branch proof)",
                "trigger_user_email": user_email,
                "step_output_keys": sorted(step_outputs.keys()),
                "actual_log_rows": log_rows,
            },
        ))
    elif branch == "catch_log_error":
        catch_payload = step_outputs.get(CATCH_AS) if isinstance(step_outputs.get(CATCH_AS), dict) else {}
        checks.append(_check(
            "catch_logs_forced_error_and_failed_try_recorded_nothing",
            str(expect.get("log_step_as") or "") == CATCH_LOG_AS
            and str(expect.get("catch_message") or "") != ""
            and catch_payload.get("message") == expect.get("catch_message")
            and expect.get("log_message") == expect.get("catch_message")
            and TRY_LOG_AS not in step_outputs
            and not any(str(row.get("as") or "") == TRY_LOG_AS for row in trace),
            {
                "reason": "the catch payload under cdf884c4 carries the forced "
                          "error, 71f22ee0 logs it verbatim, and the failed try "
                          "logger 8a8d5d15 must record nothing at all",
                "catch_payload": catch_payload,
                "step_output_keys": sorted(step_outputs.keys()),
                "actual_log_rows": log_rows,
            },
        ))
    else:
        checks.append(_check(
            "branch_is_declared",
            False,
            {
                "reason": "expect.branch must be happy_log_email or catch_log_error",
                "branch": branch,
            },
        ))

    checks.append(_check(
        "pure_mock_run_shape",
        result.get("tool_calls") == []
        and details.get("initial_snapshot") == {}
        and details.get("final_snapshot") == {}
        and raw_execution.get("return_value") is None
        and raw_execution.get("trigger_filter_matched") is True
        and not any(isinstance(row, dict) and row.get("stopped") for row in trace),
        {
            "reason": "the runtime logger never surfaces through ctx.tools and "
                      "no backend, stop node or return value exists",
            "tool_calls": result.get("tool_calls"),
            "return_value": raw_execution.get("return_value"),
        },
    ))

    return {"ok": _checks_ok(checks), "checks": checks}




