def _exclusion_projection_92048772(rows: Any) -> list[dict[str, Any]] | None:
    if not isinstance(rows, list):
        return None
    out: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            return None
        out.append({
            "EMPLOYEE_ID": row.get("EMPLOYEE_ID"),
            "ACTIVE": row.get("ACTIVE"),
            "REASON": row.get("REASON"),
        })
    return out


def _employee_projection_92048772(rows: Any) -> list[dict[str, Any]] | None:
    if not isinstance(rows, list):
        return None
    out: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            return None
        out.append({
            "ID": row.get("ID"),
            "STATUS": row.get("STATUS"),
            "FULL_NAME": row.get("FULL_NAME"),
        })
    return out


def _multiset_92048772(rows: Any) -> list[str] | None:
    import json as _json

    if not isinstance(rows, list):
        return None
    return sorted(_json.dumps(row, sort_keys=True, default=str) for row in rows)


