    checks.append(_check(
        "no_survey_response_rows_before_the_run",
        not initial_records,
        {
            "reason": "the RECIPE creates the row; the seed provisions schema only",
            "initial_records": initial_records,
        },
    ))

    create_rows = by_as.get(CREATE_STEP) or []
    slack_rows = by_as.get(SLACK_STEP) or []

    if isinstance(expect.get("created_fields"), dict):
        # --- happy path: LIVE create, catch/slack never run ---
        create_args = (create_rows[0].get("args") or {}) if create_rows else {}
        create_result = (create_rows[0].get("result") or {}) if create_rows else {}
        created_id = str(create_result.get("id") or "")
        checks.append(_check(
            "create_traced_once_with_exact_assembled_fields",
            len(create_rows) == 1
            and create_rows[0].get("tool") == "salesforce.create_record"
            and create_args.get("sobject") == SOBJECT
            and create_args.get("fields") == expect.get("created_fields")
            and create_result.get("ok") is True
            and bool(created_id),
            {
                "reason": "EXACT dict equality on all 8 assembled fields (titleize "
                          "Name, 'Responder: <email>' comment, literal Type__c, "
                          "string Score__c)",
                "expected_fields": expect.get("created_fields"),
                "actual_args": create_args,
                "actual_result": create_result,
            },
        ))
        final_record = final_records[0] if len(final_records) == 1 else {}
        final_fields = final_record.get("fields") if isinstance(final_record.get("fields"), dict) else {}
        checks.append(_check(
            "exactly_one_live_survey_response_created_with_pinned_readback",
            len(final_records) == 1
            and str(final_record.get("id") or "") == created_id
            and bool(final_fields)
            and _contains_salesforce_field_subset(final_fields, expect.get("created_record_fields") or {}),
            {
                "reason": "the final snapshot's single owned row IS the create "
                          "result's record; Score__c reads back the STRING (Text 255 "
                          "column) and Survey_Response_Date__c the Date string",
                "created_id": created_id,
                "expected_subset": expect.get("created_record_fields"),
                "actual_records": final_records,
            },
        ))
        checks.append(_check(
            "catch_branch_never_ran",
            not slack_rows and expect.get("slack") is None,
            {"reason": "the live create succeeded -- no catch, no slack post", "slack_rows": slack_rows},
        ))
    else:
        # --- catch path: forced create failure -> LIVE slack alert ---
        force = details.get("force_action_error") if isinstance(details.get("force_action_error"), dict) else {}
        forced_error = str(force.get("error") or "")
        step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
        catch_payload = step_outputs.get(CATCH_STEP) if isinstance(step_outputs.get(CATCH_STEP), dict) else {}
        checks.append(_check(
            "forced_create_never_traced_and_catch_carries_the_error_verbatim",
            not create_rows
            and bool(forced_error)
            and str(force.get("step_as") or "") == CREATE_STEP
            and str(catch_payload.get("message") or "") == forced_error,
            {
                "reason": "sanctioned fault injection on the create; the catch "
                          "payload message feeds the slack attachment_text pill",
                "force_action_error": force,
                "catch_payload": catch_payload,
                "create_rows": create_rows,
            },
        ))
        slack_args = (slack_rows[0].get("args") or {}) if slack_rows else {}
        slack_result = (slack_rows[0].get("result") or {}) if slack_rows else {}
        expected_slack = expect.get("slack") if isinstance(expect.get("slack"), dict) else {}
        expected_text = str(expected_slack.get("text") or "")
        checks.append(_check(
            "slack_alert_posted_flattened_title_and_catch_message",
            len(slack_rows) == 1
            and slack_rows[0].get("tool") == "slack.post_message"
            and bool(slack_args.get("channel"))
            and str(slack_args.get("text") or "") == expected_text
            and expected_text == f"{SLACK_TITLE}\n{forced_error}"
            and slack_result.get("ok") is True
            and bool(slack_result.get("ts")),
            {
                "reason": "channel = seeded GEARS_V2_SLACK_ERROR property routed to "
                          "the override channel; attachment flattening drops "
                          "title_link/color; a live ts proves the real post",
                "expected_text": expected_text,
                "actual_args": slack_args,
                "actual_result": slack_result,
            },
        ))
        checks.append(_check(
            "no_survey_response_row_created_on_the_catch_path",
            not final_records,
            {
                "reason": "the create failed before any live write",
                "final_records": final_records,
            },
        ))

    # --- untaken steps never trace; nothing skips or stops ---
    traced_as = {str(row.get("as") or "") for row in trace if isinstance(row, dict)}
    absent = list(expect.get("steps_absent_from_trace") or [])
    checks.append(_check(
        "untaken_branch_steps_never_traced",
        all(step_as not in traced_as for step_as in absent),
        {"expected_absent": absent, "traced_as": sorted(traced_as)},
    ))
    skipped_rows = [row for row in trace if isinstance(row, dict) and row.get("skipped") is True]
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_skip_or_stop_rows",
        not skipped_rows and not stop_rows,
        {"reason": "recipe 94001408 has no skip:true or stop steps", "trace": trace},
    ))

    # --- cleanup deleted the recipe-created row (or was a clean no-op) ---
    checks.append(_check(
        "salesforce_cleanup_deleted_owned_records",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}









