def verify_129217932(result: dict[str, Any]) -> dict[str, Any]:
    DECLARE_STEP = "4e603d35"
    COPY_STEP = "ea11a3ca"
    DELETE_STEP = "2f2a548f"
    TABLE = "SALESFORCE.EVENT_LOGS"
    STAGE = "SALESFORCE.ACTIVITY_EVENT_LOGS"
    COLUMNS = ("filename", "event_id", "event_type", "user_id", "timestamp", "detail")
    DATA_COLUMNS = ("event_id", "event_type", "user_id", "timestamp", "detail")
    base = _verify_replay_recipe(result)
