def _normalize_created_row_126049785(row: Any) -> dict[str, Any] | None:
    """Normalize a live created-table row (dual-case keys, DATE isoformat,
    NUMBER ints, listagg strings) into the pinned shape: scalar columns typed,
    listagg columns as SORTED title lists ('' -> [])."""
    if not isinstance(row, dict):
        return None
    out: dict[str, Any] = {}
    for col in _SCALAR_COLS_126049785:
        value = row.get(col)
        if col in _INT_COLS_126049785:
            try:
                out[col] = int(value)
            except (TypeError, ValueError):
                return None
        else:
            out[col] = str(value)
    for col in _LISTAGG_COLS_126049785:
        value = row.get(col)
        text = "" if value is None else str(value)
        out[col] = sorted(part for part in text.split(";") if part)
    return out


def _multiset_126049785(rows: Any) -> list[str]:
    import json as _json

    return sorted(
        _json.dumps(row, sort_keys=True, default=str)
        for row in (rows if isinstance(rows, list) else [])
    )


def _derived_created_rows_126049785(
    initial_sf: dict[str, Any], now: str
) -> list[dict[str, Any]] | None:
    """Re-derive the CTAS contents from the live pre-run snapshot + the
    pinned instant. Returns None when the snapshot is unusable or ambiguous
    (fan-out the seeder is required to prevent)."""
    import datetime as _dt

    tables: dict[str, list[dict[str, Any]]] = {}
    for name in _SOURCE_TABLES_126049785:
        rows = initial_sf.get(name)
        if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
            return None
        tables[name] = rows
    try:
        parsed = _dt.datetime.fromisoformat(str(now).replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return None
    snap_date = parsed.strftime("%Y-%m-%d")
    app_entry_date = (parsed.date() - _dt.timedelta(days=1)).isoformat()
    # account_data: window + flags, one survivor per account (rn = 1)
    account_data: dict[str, dict[str, Any]] = {}
    for row in tables[_ACCOUNTS_TABLE_126049785]:
        if (
            str(row.get("startdate")) >= _WINDOW_START_126049785
            and str(row.get("startdate")) <= snap_date
            and row.get("is_paying") is True
            and row.get("is_direct") is True
        ):
            if str(row.get("account_id")) in account_data:
                return None
            account_data[str(row.get("account_id"))] = row
    # first_sha_dates: success-only, min timestamps per shared account
    sha_groups: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for row in tables[_SHARED_TABLE_126049785]:
        if str(row.get("authorization_status")) != "success":
            continue
        key = (
            str(row.get("id")),
            str(row.get("data_center")),
            str(row.get("user_id")),
            str(row.get("provider")),
        )
        group = sha_groups.setdefault(
            key,
            {"auth": str(row.get("authorized_at")), "created": str(row.get("created_at"))},
        )
        group["auth"] = min(group["auth"], str(row.get("authorized_at")))
        group["created"] = min(group["created"], str(row.get("created_at")))
    # mapped_first_sha_dates: LEFT JOIN yesterday's application snapshot
    mapped: list[dict[str, Any]] = []
    for (sha_id, data_center, user_id, provider), group in sha_groups.items():
        apps = [
            app
            for app in tables[_APPS_TABLE_126049785]
            if str(app.get("data_center")) == data_center
            and str(app.get("name")) == provider
            and str(app.get("entry_date")) == app_entry_date
        ]
        if len(apps) > 1:
            return None
        app = apps[0] if apps else None
        title = str(app.get("title")) if app and app.get("title") else provider
        category = app.get("category") if app else None
        mapped.append(
            {
                "data_center": data_center,
                "user_id": user_id,
                "title": title,
                "category": category,
                "auth": group["auth"],
                "created": group["created"],
            }
        )
    # app_first_events: min per (dc, user, title, category)
    events: dict[tuple[str, str, str, Any], dict[str, str]] = {}
    for row in mapped:
        key = (row["data_center"], row["user_id"], row["title"], row["category"])
        event = events.setdefault(key, {"auth": row["auth"], "created": row["created"]})
        event["auth"] = min(event["auth"], row["auth"])
        event["created"] = min(event["created"], row["created"])
    # app_interim: Monday-of-week calendar joins (INNER)
    calendar = tables[_CALENDAR_TABLE_126049785]

    def _monday(day: str) -> str | None:
        day_rows = [row for row in calendar if str(row.get("date")) == day]
        if len(day_rows) != 1:
            return None
        year, week = day_rows[0].get("year"), day_rows[0].get("week")
        mondays = [
            row
            for row in calendar
            if row.get("year") == year
            and row.get("week") == week
            and str(row.get("dayname")) == "Mon"
        ]
        if len(mondays) != 1:
            return None
        return str(mondays[0].get("date"))

    interim: list[dict[str, Any]] = []
    for (data_center, user_id, title, category), event in events.items():
        belonging_conn = _monday(str(event["auth"])[:10])
        belonging_creation = _monday(str(event["created"])[:10])
        if belonging_conn is None or belonging_creation is None:
            return None
        interim.append(
            {
                "data_center": data_center,
                "user_id": user_id,
                "title": title,
                "category": category,
                "belonging_conn": belonging_conn,
            }
        )
    # app_interim2: latest paid workspace -> sales account
    interim2: list[dict[str, Any]] = []
    for row in interim:
        workspaces = [
            wd
            for wd in tables[_WORKSPACE_TABLE_126049785]
            if str(wd.get("workspace_id")) == row["user_id"]
            and str(wd.get("data_center")) == row["data_center"]
            and wd.get("is_latest") is True
            and wd.get("is_paid_workspace") is True
        ]
        if len(workspaces) > 1:
            return None
        if not workspaces:
            continue
        interim2.append(row | {"account_id": str(workspaces[0].get("sales_account_id"))})
    # app_interim3: account_data join, tier CASE, connected flag
    tier_by_title: dict[str, list[dict[str, Any]]] = {}
    for tier in tables[_TIER_TABLE_126049785]:
        tier_by_title.setdefault(str(tier.get("title")), []).append(tier)
    if any(len(rows) > 1 for rows in tier_by_title.values()):
        return None
    groups: dict[tuple[Any, ...], dict[str, Any]] = {}
    for row in interim2:
        account = account_data.get(row["account_id"])
        if account is None:
            continue
        tier_rows = tier_by_title.get(row["title"]) or []
        tier = tier_rows[0] if tier_rows else None
        at_category = tier.get("category") if tier else None
        if at_category in ("workato", "others") or at_category is None:
            app_tier = 5
        else:
            app_tier = int(tier["app_tier"]) if tier.get("app_tier") is not None else 5
        connected_flag = (
            0
            if str(row["belonging_conn"]) < str(account.get("subscription_start_date"))
            else 1
        )
        key = (
            row["account_id"],
            str(account.get("account_name")),
            str(account.get("subscription_start_date")),
            row["title"],
            row["category"],
            connected_flag,
            app_tier,
        )
