    truncate_result = (truncate_rows[0].get("result") or {}) if truncate_rows else {}
    checks.append(_check(
        "truncate_deleted_preseeded_row_count",
        len(truncate_rows) == 1
        and truncate_result.get("deleted_rows") == expect.get("truncate_deleted_rows")
        and str(truncate_result.get("lookup_table_id") or "") == _LOOKUP_TABLE_130008586,
        {
            "expected_deleted_rows": expect.get("truncate_deleted_rows"),
            "actual_truncate_rows": truncate_rows,
        },
    ))

    # --- batch add: ORDERED entries + added_count pinned ---
    batch_rows = by_as.get(BATCH_STEP) or []
    batch_args = (batch_rows[0].get("args") or {}) if batch_rows else {}
    batch_result = (batch_rows[0].get("result") or {}) if batch_rows else {}
    checks.append(_check(
        "batch_entries_match_pinned_order",
        len(batch_rows) == 1
        and batch_rows[0].get("tool") == "lookup_table.add_batch_of_entries"
        and batch_args.get("entries") == list(expect.get("batch_entries_ordered") or [])
        and batch_result.get("added_count") == len(expect.get("batch_entries_ordered") or []),
        {
            "expected_entries": expect.get("batch_entries_ordered"),
            "actual_entries": batch_args.get("entries"),
            "actual_result": batch_result,
        },
    ))

    # --- final lookup table: ordered replacement of the stale rows ---
    # (the 0-rows case leaves the table truncated-EMPTY: count 0, rows [])
    final_rows = (
        (final_snapshot.get("lookup_table") or {}).get("tables", {}).get(_LOOKUP_TABLE_130008586, [])
    )
    final_public = [_public_row_130008586(row) for row in final_rows]
    checks.append(_check(
        "final_lookup_table_matches_pinned_order",
        len(final_rows) == expect.get("final_row_count")
        and final_public == list(expect.get("final_lookup_rows_ordered") or []),
        {
            "expected_row_count": expect.get("final_row_count"),
            "expected_rows": expect.get("final_lookup_rows_ordered"),
            "actual_rows": final_public,
        },
    ))

    # --- Snowflake is READ-ONLY here: the one live table unchanged ---
    final_sf = (final_snapshot.get("snowflake") or {}).get("tables", {})
    checks.append(_check(
        "snowflake_snapshot_unchanged",
        isinstance(initial_sf, dict)
        and sorted(initial_sf) == [_CATALOG_TABLE_130008586]
        and initial_sf == final_sf,
        {"initial_tables": initial_sf, "final_tables": final_sf},
    ))

    # --- cleanup dropped exactly the seeded live table ---
    checks.append(_check(
        "snowflake_cleanup_dropped_seeded_table",
        bool(cleanup_response.get("ok"))
        and sorted(cleanup_response.get("dropped_tables") or []) == [_CATALOG_TABLE_130008586],
        {"cleanup_response": cleanup_response},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}



