    # Dead-branch attestation: each pinned decoy must appear in the initial
    # snapshot with a live read-back that passes every seedable arm while its
    # REAL RecordTypeId differs from the recipe's foreign literal.
    snapshot_records = (
        ((details.get("initial_snapshot") or {}).get("salesforce") or {}).get("records") or []
    )
    events = [
        row.get("fields") or {}
        for row in snapshot_records
        if isinstance(row, dict) and str(row.get("sobject") or "") == "Event"
    ]
    expected_decoys = expect.get("decoy_events") if isinstance(expect.get("decoy_events"), list) else []
    matched = []
    for decoy in expected_decoys:
        if not isinstance(decoy, dict):
            matched.append({"decoy": decoy, "ok": False})
            continue
        hit = next(
            (
                fields for fields in events
                if str(fields.get("Type") or "") == str(decoy.get("Type") or "")
                and str(fields.get("AccountId") or "") == str(decoy.get("AccountId") or "")
                and str(fields.get("OwnerId") or "") == str(decoy.get("OwnerId") or "")
                and fields.get("IsDeleted") in (False, "false")
                and str(fields.get("RecordTypeId") or "") != _FOREIGN_RT_103988481
            ),
            None,
        )
        matched.append({"decoy": decoy, "ok": hit is not None, "live_fields": hit})
    checks.append(_check(
        "decoy_events_prove_rt_arm_is_the_excluder",
        bool(expected_decoys) and all(entry["ok"] for entry in matched),
        {
            "reason": "zero-match honesty: the seeded decoy Event's live read-back "
                      "satisfies Type/AccountId/OwnerId/IsDeleted while its REAL "
                      "RecordTypeId is not the foreign literal -- the empty result is "
                      "attributable to the WHERE, never to an empty org",
            "empty_reason": expect.get("empty_reason"),
            "expected_decoys": expected_decoys,
            "match_details": matched,
            "snapshot_events": events,
        },
    ))

    cleanup_response = details.get("cleanup_response") or {}
    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


